  assert.strictEqual(C.mirrorSpeakerLines('- 甲。- 乙。- 丙。', '- A.\n- B.'), '- 甲。- 乙。- 丙。');
  assert.strictEqual(C.mirrorSpeakerLines('- 甲。\n- 乙。', '- A.\n- B.'), '- 甲。\n- 乙。');
