    assert.ok(/return \(f === 'vtt' \|\| f === 'vtt-styled'\) \? 'vtt'/.test(mg), 'vtt-styled 的扩展名不是 .vtt');
    /* ASS 面板与 VTT 面板互斥（两套单位不同，不能同时摆着） */
    assert.ok(/\$\('assPanel'\)\.style\.display = \(plain \|\| tpl === 'vttStyle'\) \? 'none' : ''/.test(mg),
      '选了 VTT 样式却还把 ASS 面板摆着');
