    assert.ok(/<td class="ed" data-ed="dst" data-ri="'\+i\+'">/.test(mg), '译文格不可编辑');
    /* 编辑过的行要有看得见的标记 */
    assert.ok(/const dot = r\.edited \? '<i class="ed-dot" title="'\+esc\(t\('edEdited'\)\)\+\'"><\/i>' : '';/.test(mg),
      '编辑过的行没有标记（用户看不出哪条改过）');
