  /* ==========================================================================
     v0.9.303：双语对（形态 B）不该被体检当成「重叠」
     用户反馈：一份「原文一条 + 译文一条」的双语字幕，体检把每一对的第二条都报成 overlap。
     根因在 checkCues —— overlap 只看「时间有没有重合」，不认「这两条是不是同一句的两种语言」。
     连带的更要命：建议里给的「往后挪开」会把译文挪到原文之后 100ms，那才是真把双语毁了。
     所以判据要落在「是不是一对」上（isBilingualPair），不是「时间有没有重合」上。
     红线：
       ① 只豁免「起止对得上 + 分属两套书写系统」的一对，真重叠与真重复照报；
       ② 动一条必须带动伙伴 —— 只改一条会让两条错开，下一轮体检又报重叠（二次 bug）；
       ③ 切开 / 合并这两类会破坏双语结构的建议，一律不给（跟形态 A 一个道理）；
       ④ 单语字幕的老行为一个字都不许变。
     ========================================================================== */
  const RB = SHF.uiRules({}, 'srt');
  const mk = arr => arr.map(p => ({ start: p[0], end: p[1], text: p[2] }));
  const nOv = list => SHF.checkCues(list, RB).filter(b => b.why.indexOf('overlap') >= 0).length;

  t('v0.9.303：形态 B 的双语对（两条同轴）不再报重叠 —— 用户报的那个 bug', () => {
    const two = mk([[1000, 3000, 'Hello world'], [1000, 3000, '你好世界'],
      [4000, 6000, 'How are you'], [4000, 6000, '你好吗']]);
    assert.strictEqual(nOv(two), 0, '两对中英同轴还报了重叠：' + J(SHF.checkCues(two, RB)));
    assert.strictEqual(SHF.checkCues(two, RB).length, 0, '整份应无问题：' + J(SHF.checkCues(two, RB)));
    /* 判据按「书写系统」分，不按「是不是中文」分 —— 六种系统两两组合都得认 */
    [['日英', 'こんにちは', 'Hello'], ['韩英', '안녕하세요', 'Hello'],
      ['俄英', 'Привет мир', 'Hello'], ['阿英', 'مرحبا', 'Hello'],
      ['希英', 'Γειά σου', 'Hello'], ['泰英', 'สวัสดีครับ', 'Hello']].forEach(p => {
        const c = mk([[1000, 3000, p[2]], [1000, 3000, p[1]]]);
        assert.strictEqual(nOv(c), 0, p[0] + ' 双语对被当成重叠了');
      });
  });

  t('v0.9.303：同轴容差 —— 帧率舍入级的偏差放过，真错位照报', () => {
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello world'], [1050, 3000, '你好世界']])), 0,
      '起点差 50ms（帧率换算级别）不该报');
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello world'], [1100, 3050, '你好世界']])), 0,
      '起止各差 100/50ms 仍在容差内');
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello world'], [1000, 3100, '你好世界']])), 0,
      '终点差 100ms 在容差内，放过');
    /* 起点差 400ms = 两条没对齐；终点差 600ms = 一条先消失。都是真问题，不许豁免 */
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello world'], [1400, 3000, '你好世界']])), 1,
      '起点差 400ms（真错位）应照报');
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello world'], [1000, 3600, '你好世界']])), 1,
      '终点差 600ms（时长不一致，一条先消失）应照报');
  });

  t('v0.9.303：防过度豁免 —— 该报的一条都没放过去', () => {
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello world'], [1000, 3000, 'Hello again']])), 1,
      '同语言完全同轴 = 真重复，必须报');
    assert.strictEqual(nOv(mk([[1000, 3500, 'Hello world'], [3000, 5000, 'How are you']])), 1,
      '真重叠（尾巴压头）必须报');
    /* 一方认不出书写系统（纯数字 / 纯标点）就不认这一对 —— 宁可让人看一眼，也不悄悄放过 */
    assert.ok(nOv(mk([[1000, 3000, 'Hello world'], [1000, 3000, '1234']])) >= 1,
      '一方是纯数字，不该被当成双语对');
    assert.ok(nOv(mk([[1000, 3000, 'Hello world'], [1000, 3000, '!!!']])) >= 1,
      '一方是纯标点，不该被当成双语对');
    /* 三语字幕：三条同轴也照认 */
    assert.strictEqual(nOv(mk([[1000, 3000, 'Hello'], [1000, 3000, '你好'], [1000, 3000, 'Bonjour']])), 0,
      '三语三条同轴被当成重叠了');
  });

  /* ⚠️ v0.9.304：双语对整条豁免 short / long / fast / line 之后，「延长」这条建议
     在双语对上就走不到了。但「动一条必须带动伙伴」这条原则一条都没松 ——
     改由「一对跟上一句重叠 → 往后挪」这条路径来验证（下面两条）。 */
  const pushPair = () => mk([[1000, 5000, 'Hello world'], [1000, 5000, '你好世界'],
    [4000, 6000, 'Next sentence'], [4000, 6000, '下一句']]);

  t('v0.9.303：动一条必须带动伙伴 —— 只改一条会滚出二次 bug（挪动后错开又报重叠）', () => {
    const pr = pushPair();
    const bad = SHF.checkCues(pr, RB);
    assert.strictEqual(bad.length, 1, '只有第 3 条跟上一句重叠：' + J(bad));
    assert.strictEqual(bad[0].i, 2, '报的应该是第 3 条（下标 2）');
    const sg = SHF.suggest(pr, bad[0], RB);
    const push = sg.filter(s => s.k === 'btnPush')[0];
    assert.ok(push, '给不出「往后挪」建议：' + J(sg.map(s => s.k)));
    /* 关键：一组两条，不是一条 —— 只挪一条会让这一对内部错开 */
    assert.ok(Array.isArray(push.op) && push.op.length === 2,
      '挪动建议必须是成组的两条操作，实际：' + J(push.op));
    const after = SHF.applyOps(pr, [push.op]);
    assert.strictEqual(after.length, 4, '条目数不该变（没被合并或切开）');
    assert.ok(Math.abs(after[2].start - after[3].start) <= SHF.ALIGN_TOL
      && Math.abs(after[2].end - after[3].end) <= SHF.ALIGN_TOL,
      '挪完第 3、4 条仍然同轴，否则下一轮体检又报重叠：' + J(after.slice(2)));
    assert.strictEqual(SHF.checkCues(after, RB).length, 0,
      '采纳后重跑体检应无问题：' + J(SHF.checkCues(after, RB)));
  });

  t('v0.9.303：保留原来的起止偏差 —— 有的字幕是故意让译文晚几十毫秒的', () => {
    /* 第 4 条（译文）比第 3 条晚 80ms 出现、同时消失 */
    const pr = mk([[1000, 5000, 'Hello world'], [1000, 5000, '你好世界'],
      [4000, 6000, 'Next sentence'], [4080, 6000, '下一句']]);
    const bad = SHF.checkCues(pr, RB);
    const push = SHF.suggest(pr, bad[0], RB).filter(s => s.k === 'btnPush')[0];
    assert.ok(push, '给不出挪动建议：' + J(bad));
    const after = SHF.applyOps(pr, [push.op]);
    assert.strictEqual(after[3].start - after[2].start, 80,
      '两条起点那 80ms 的偏差被顺手抹平了 —— 那是用户故意的，实际：'
      + (after[3].start - after[2].start));
    assert.strictEqual(after[3].end - after[2].end, 0,
      '终点本来是齐的，挪完反倒错开了：' + (after[3].end - after[2].end));
  });

  t('v0.9.303：会破坏双语结构的建议一律不给（切开 / 合并）', () => {
    /* ⚠️ v0.9.304 实测修掉的坑：prevTemporal 会跳过同轴伙伴，所以 prev 未必是 list[i-1]。
       「与前一条合并」的下标要是写死 i-1，就会把**上一句的译文**和**这一句的原文**
       并成一条（实测结果："你好世界\nNext sentence"），字幕直接串味。 */
    const pr = pushPair();
    const bad = SHF.checkCues(pr, RB);
    const keys = SHF.suggest(pr, bad[0], RB).map(s => s.k);
    assert.ok(keys.indexOf('btnMergePrev') < 0,
      '给了「与前一条合并」，会把上一句译文和这一句原文并成一条：' + keys);
    assert.ok(keys.indexOf('btnMergeNext') < 0, '给了「与后一条合并」：' + keys);
    assert.ok(keys.indexOf('btnSplit') < 0, '给了「切开」：' + keys);
    /* 采纳之后，任何一条里都不许出现「译文和下一句原文挤在一起」 */
    const push = SHF.suggest(pr, bad[0], RB).filter(s => s.k === 'btnPush')[0];
    const after = SHF.applyOps(pr, [push.op]);
    after.forEach(c => {
      assert.ok(!(c.text.indexOf('你好世界') >= 0 && c.text.indexOf('Next') >= 0),
        '采纳后出现了串味条目：' + J(after.map(x => x.text)));
    });
    /* 形态 A（一条两行）同样不给切开：整条豁免后体检走不到，直接查 suggest 的兜底过滤 */
    const a = mk([[1000, 13000, 'This is a very long English sentence\n这是一句非常长的中文']]);
    assert.ok(!SHF.checkCues(a, RB).some(x => x.why.indexOf('long') >= 0), '形态 A 不该报 long');
    assert.ok(SHF.isBilingualEntry(a, 0), '形态 A 该被认成双语条目');
  });

  t('v0.9.303：单语字幕的老行为一个字都不许变（回归）', () => {
    const mono = mk([[1000, 3000, 'Hello world'], [3000, 5000, 'How are you'],
      [5200, 7000, 'Fine thanks']]);
    assert.strictEqual(SHF.checkCues(mono, RB).length, 0, '首尾相接 + 小空档不该报：'
      + J(SHF.checkCues(mono, RB)));
    const ov = mk([[1000, 3500, 'Hello world'], [3000, 5000, 'How are you']]);
    const hit = SHF.checkCues(ov, RB);
    assert.strictEqual(hit.length, 1, '单语真重叠没报：' + J(hit));
    const sg = SHF.suggest(ov, hit[0], RB);
    assert.ok(sg.filter(s => s.k === 'btnPush').length === 1, '单语重叠仍要给「往后挪开」：'
      + J(sg.map(s => s.k)));
    /* ⚠️ 反向断言：单语的建议必须是**单个**操作对象，不能变成数组
       —— 老 ops（292/294 留下的）页面 pushOp 是逐个 push 的，形状一变撤销栈就乱了 */
    assert.ok(sg.every(s => !Array.isArray(s.op)), '单语建议被改成数组了，会破坏老行为');
    /* applyOps 仍吃扁平的老格式 */
    const r = SHF.applyOps(ov, [{ op: 'set', i: 1, s: 3600, e: 5600 }]);
    assert.strictEqual(r.length, 2, '扁平 ops 失效了');
    assert.strictEqual(r[1].start, 3600, '扁平 ops 没生效');
  });

  t('v0.9.303：形态 A（一条两行）不受影响（回归）', () => {
    const a = mk([[1000, 3000, 'Hello world\n你好世界']]);
    assert.strictEqual(SHF.checkCues(a, RB).length, 0, '形态 A 双语条目不该报：' + J(SHF.checkCues(a, RB)));
    assert.ok(SHF.isBilingualCue(a[0]), '形态 A 仍要是双语条目');
    /* 形态 B 的两条各自是单语的，不该被 isBilingualCue 认成双语 —— 两条判据各管一段 */
    const b = mk([[1000, 3000, 'Hello world'], [1000, 3000, '你好世界']]);
    assert.ok(!SHF.isBilingualCue(b[0]), '形态 B 的单条不该被 isBilingualCue 认成双语');
    assert.ok(SHF.isBilingualPair(b[0], b[1]), '形态 B 的两条该被 isBilingualPair 认成一对');
  });

  /* ==========================================================================
     v0.9.304：双语的两种写法，体检口径统一
     背景：双语字幕有两种写法 —— 形态 A（一条里两行：原文一行 + 译文一行）、
     形态 B（两条同轴：一条原文、一条译文）。两者在播放器里看到的**完全一样**
     （上面一行、下面一行、同时显示），但 304 之前体检口径不同：
       形态 A：认出是双语 → 整条豁免停留 / 停留过长 / 读速 / 行宽 / 行数
       形态 B：每条只有一种文字，认不出 → 按单语逐条查
     真实素材实测：71 条形态 A 报 0 条；同样的内容拆成 142 条形态 B 报 59 条
     （停留太短 34 / 读太快 25 / 行太宽 9）。屏幕上看不出区别，结果差这么多，说不通。
     用户拍板统一：形态 B 也按双语处理（isBilingualEntry 是唯一入口）。

     红线（绝不能因为「统一」就一路豁免到底）：
       ① 同轴但**不是**一对的（两条都英文、时间还撞一起）是屏幕叠字，照查；
       ② 认不出书写系统的（纯数字 / 纯标点）不算一对，宁可报出来让人看一眼；
       ③ 动一条必须带动伙伴 —— 303 定的原则一条没松。

     顺带修掉 303 在 overlap 分支漏的两刀：
       ·「与前一条合并」的下标写死 i - 1，而 prevTemporal 会跳过同轴伙伴，
         于是把**上一句的译文**和**这一句的原文**并成一条（实测 "你好世界\nNext sentence"）；
       ·「往后挪」没成对，挪完伙伴留在原地，两条错开又报重叠。
     ========================================================================== */
  const mkA = (s, e, t1, t2) => mk([[s, e, t1 + '\n' + t2]]);
  const mkB = (s, e, t1, t2) => mk([[s, e, t1], [s, e, t2]]);
  const nWhy = (list, w) => SHF.checkCues(list, RB).filter(b => b.why.indexOf(w) >= 0).length;

  t('v0.9.304：同一句双语，形态 A 与形态 B 的体检结论必须一致', () => {
    /* 五把尺子各来一组，每组都挑「按单语看肯定超标、按双语看正常」的参数 */
    const cases = [
      ['停留太短 500ms', 1000, 1500, 'Hello world', '你好世界'],
      ['停留太久 12s', 1000, 13000, 'This is a very long English sentence', '这是一句非常长的中文'],
      ['一行太宽 60 字符', 1000, 4000, 'This sentence is quite long and will overflow the line width', '这句话有点长'],
      ['一条三行', 1000, 4000, 'Line one\nLine two\nLine three', '第一行\n第二行\n第三行']
    ];
    cases.forEach(c => {
      const ra = SHF.checkCues(mkA(c[1], c[2], c[3], c[4]), RB);
      const rb = SHF.checkCues(mkB(c[1], c[2], c[3], c[4]), RB);
      assert.strictEqual(ra.length, 0, c[0] + '：形态 A 不该报：' + J(ra));
      assert.strictEqual(rb.length, 0, c[0] + '：形态 B 不该报（口径要跟形态 A 一致）：' + J(rb));
    });
  });

  t('v0.9.304：形态 B 的两条都被认成双语条目（整条豁免，不是只豁免第二条）', () => {
    const b = mkB(1000, 1500, 'Hello world', '你好世界');
    assert.ok(SHF.isBilingualEntry(b, 0), '原文那条该被认成双语条目');
    assert.ok(SHF.isBilingualEntry(b, 1), '译文那条该被认成双语条目');
    assert.ok(SHF.isBilingualMate(b, 0) && SHF.isBilingualMate(b, 1), '两条都该被认出有同轴伙伴');
    ['short', 'long', 'fast', 'line', 'rows', 'overlap'].forEach(w => {
      assert.strictEqual(nWhy(b, w), 0, '形态 B 报了 ' + w + '：' + J(SHF.checkCues(b, RB)));
    });
  });

  t('v0.9.304：防过度豁免 —— 同轴但**不是**双语对的，原来怎么查还怎么查', () => {
    /* 两条都是英文、时间还撞一起 = 屏幕叠字，真问题，不许因为「同轴」就放过 */
    const same = mk([[1000, 3000, 'Hello world'], [2000, 4000, 'How are you']]);
    assert.strictEqual(nOv(same), 1, '同语言同轴（真重复）照报：' + J(SHF.checkCues(same, RB)));
    assert.ok(!SHF.isBilingualEntry(same, 0), '两条都是英文，不该被认成双语条目');
    assert.ok(!SHF.isBilingualEntry(same, 1), '两条都是英文，不该被认成双语条目');
    /* 既然不是双语，五把尺子照量：两条各 300ms，全该报停留太短 */
    const twoShort = mk([[1000, 1300, 'Hello'], [1000, 1300, 'World']]);
    assert.strictEqual(nWhy(twoShort, 'short'), 2,
      '同轴的两条英文各 300ms，两条都该报停留太短：' + J(SHF.checkCues(twoShort, RB)));
    /* 认不出书写系统的（纯数字）不算一对 —— 宁可报出来让人看一眼 */
    const num = mk([[1000, 3000, '2024'], [1000, 3000, '你好世界']]);
    assert.ok(!SHF.isBilingualPair(num[0], num[1]), '纯数字认不出书写系统，不该算一对');
  });

  t('v0.9.304：双语处数统计 —— 形态 A 一条算一处，形态 B 一对算一处', () => {
    assert.strictEqual(SHF.bilingualCount(mkA(1000, 3000, 'Hello', '你好')), 1, '形态 A 一条算一处');
    assert.strictEqual(SHF.bilingualCount(mkB(1000, 3000, 'Hello', '你好')), 1,
      '形态 B 一对算一处（不能数成两条），实际：'
      + SHF.bilingualCount(mkB(1000, 3000, 'Hello', '你好')));
    const two = mk([[1000, 3000, 'Hello'], [1000, 3000, '你好'],
      [4000, 6000, 'Bye'], [4000, 6000, '再见']]);
    assert.strictEqual(SHF.bilingualCount(two), 2, '两对应是两处，实际：' + SHF.bilingualCount(two));
    assert.strictEqual(SHF.bilingualCount(mk([[1000, 3000, 'Hello world']])), 0, '单语不该数出双语');
    assert.strictEqual(SHF.bilingualCount([]), 0, '空列表不该报错');
  });

  t('v0.9.304：页面把认出来的双语显示出来（chkBil）', () => {
    const SH = readT('shift.html');
    assert.ok(/id="chkBil"/.test(SH), '体检面板没有双语提示元素');
    assert.ok(/bilingualCount\(/.test(SH), '页面没调 bilingualCount');
    assert.ok(/tpl\('chkBil'/.test(SH), '提示文案没走词典（写死中文，26 门语言看不懂）');
    /* 这行带数字，不走 data-i18n —— 换语言必须自己重画，否则提示还停在上一门语言 */
    const i = SH.indexOf('function applyI18n');
    assert.ok(i > 0, '找不到 applyI18n');
    assert.ok(SH.slice(i, i + 1400).indexOf('renderCheck()') > 0,
      'applyI18n 里没有 renderCheck() —— 换语言后双语提示还停在上一门语言');
  });

  t('v0.9.304：chkBil 词条 27 语齐全（缺一门，那门语言下就显示键名）', () => {
    const vm2 = require('vm');
    const b = { window: {}, console: console }; b.global = b; vm2.createContext(b);
    vm2.runInContext(readT('shift-i18n.js'), b, { filename: 'shift-i18n.js' });
    const SI = b.window.SHIFT_I18N;
    assert.ok(SI && SI.LANGS.length === 27, 'shift-i18n.js 没读出 27 语');
    const RE_HAN = /[\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]/;
    SI.LANGS.forEach(([l]) => {
      const v = SI.DICT[l].chkBil;
      assert.ok(typeof v === 'string' && v.length > 0, l + ' 缺 chkBil');
      assert.ok(v.indexOf('{0}') >= 0, l + ' 的 chkBil 丢了占位符：' + v);
      if (!/^(zh-CN|zh-TW|ja)$/.test(l)) {
        assert.ok(!RE_HAN.test(v), l + ' 的 chkBil 混进了汉字：' + v);
      }
    });
  });

  /* ==========================================================================
     v0.9.305：形态 B 在「逐条微调」里的呈现 —— 分开调，但结构要看得见
     背景：304 统一了**体检**口径（形态 A ≡ 形态 B），但微调层还把一对当两条独立 cue。
     实测（形态 B，20 句 40 条）暴露三件事：
       ① 列表里形态 B 的两行没有任何配对标记（isBilingualCue 单条都是 false），
          跟任意两条独立字幕长得一模一样 —— 用户看不出是一对，才会手滑只改一条；
       ② 只改一条 → 两条错开超过 120ms → 体检立刻报 overlap（303 那个 bug 的翻版）；
       ③ 切分漏了护栏：applyOps 的 split 只挡了形态 A（写的 isBilingualCue），形态 B 漏网，
          原文被切开、译文留在原地，一对就这么散了（实测多报 1 overlap + 1 short）。
     用户拍板：**分开调**，保留自己定原文/译文时间轴的自由 —— 强制绑定是过度设计。
     工具该做的是「可见 + 护栏 + 可复原」，所以本版：
       · 一对在列表里串成一组（.pg，左边一道竖线），两条各自保留独立时间框；
       · 双语条目（A 和 B）都不给切分按钮，引擎层守卫也从 A 扩到 B；
       · 两条被调开时明说后果，并给「对齐」按钮（成组两个 set op，撤销一次撤一整组）。
     ========================================================================== */
  t('v0.9.305：配对不许切 —— applyOps 的 split 守卫从形态 A 扩到形态 B', () => {
    const b = mkB(1000, 2800, 'Hello world', '你好世界');
    const r0 = SHF.applyOps(b, [{ op: 'split', i: 0 }]);
    assert.strictEqual(r0.length, 2, '形态 B 的原文切不动，实际条数：' + r0.length);
    assert.strictEqual(r0[0].text, 'Hello world', '切不动时文本一字未动');
    assert.strictEqual(SHF.applyOps(b, [{ op: 'split', i: 1 }]).length, 2, '形态 B 的译文也切不动');
    /* 形态 A 的护栏 304 之前就有，别改坏 */
    const a = mkA(1000, 2800, 'Hello world', '你好世界');
    assert.strictEqual(SHF.applyOps(a, [{ op: 'split', i: 0 }]).length, 1, '形态 A 仍然切不动');
    /* 单语条目照切 —— 别为了拦双语把正常功能关了 */
    const m = mk([[0, 3000, 'First half of a long sentence here'], [3100, 6000, 'Second half here']]);
    assert.ok(SHF.applyOps(m, [{ op: 'split', i: 0 }]).length >= 3, '普通单语条目照样能切');
  });

  t('v0.9.305：unalignedPair 认「被调开的一对」，不认正常流水', () => {
    const b = mkB(1000, 2800, 'Hello world', '你好世界');
    assert.strictEqual(SHF.unalignedPair(b, 0), null, '同轴的一对归 isBilingualPair 管，这里不报');

    const off = mk([[1000, 3100, 'Hello world'], [1000, 2800, '你好世界']]);
    const u = SHF.unalignedPair(off, 0);
    assert.ok(u && u.j === 1, '终点错开 300ms 该报出伙伴');
    assert.strictEqual(u.off, 300, '偏差该是 300ms，实际：' + (u && u.off));
    assert.ok(SHF.unalignedPair(off, 1), '从译文那侧查也该查得到');

    /* 两道闸门，缺一个就会把正常流水认成「被拆散的一对」 */
    const seq = mk([[0, 2000, 'First sentence in english'], [2000, 4000, '第二句话']]);
    assert.strictEqual(SHF.unalignedPair(seq, 0), null, '首尾相接的中英流水不是被拆散的一对');
    const nar = mk([[0, 5000, 'A long english narration'], [4000, 6000, '中文解说']]);
    assert.strictEqual(SHF.unalignedPair(nar, 0), null, '只重叠一半的是各说各的，不是一对');
    const same = mk([[0, 3000, 'English line'], [0, 2500, 'Another english line']]);
    assert.strictEqual(SHF.unalignedPair(same, 0), null, '同语言同轴是屏幕叠字，归 overlap 管');
  });

  t('v0.9.305：alignOps 取并集，一组两个 op，对齐后重新被认成一对', () => {
    const off = mk([[1000, 3100, 'Hello world'], [1000, 2800, '你好世界']]);
    const ops = SHF.alignOps(off, 0);
    assert.ok(Array.isArray(ops) && ops.length === 2, '该返回一组两个 op');
    assert.ok(ops.every(o => o.op === 'set'), '两个 op 都该是 set');
    assert.strictEqual(ops[0].i, 0, '第一条 op 对着原文');
    assert.strictEqual(ops[1].i, 1, '第二条 op 对着译文');
    assert.strictEqual(ops[0].s, 1000, '起点取 min');
    assert.strictEqual(ops[0].e, 3100, '终点取 max（并集，不把另一条截短）');

    const fixed = SHF.applyOps(off, ops);
    assert.strictEqual(fixed[0].start, fixed[1].start, '对齐后起点相同');
    assert.strictEqual(fixed[0].end, fixed[1].end, '对齐后终点相同');
    assert.strictEqual(fixed[0].end, 3100, '终点是并集 3100，不是被缩短的 2800');
    assert.ok(SHF.isBilingualPair(fixed[0], fixed[1]), '对齐后重新被认成一对');
    assert.strictEqual(SHF.unalignedPair(fixed, 0), null, '对齐后不该再报不同轴');
    assert.strictEqual(SHF.checkCues(fixed, RB).length, 0, '对齐后这一对自身体检 0 条');
    assert.ok(SHF.checkCues(off, RB).length >= 1, '对齐前确实报了（这一对已经被调开）');
    assert.strictEqual(SHF.alignOps(mkB(1000, 2800, 'a', '中'), 0), null, '本来就同轴的不用对齐');
  });

  t('v0.9.305：isPairGroup —— 被调开的一对仍算一组（不能一调开就散）', () => {
    const b = mkB(1000, 2800, 'Hello world', '你好世界');
    assert.strictEqual(SHF.isPairGroup(b, 0), true, '同轴的一对算一组');
    assert.strictEqual(SHF.isPairGroup(b, 1), false, '组里第二条不再领一个组');
    const off = mk([[1000, 3100, 'Hello world'], [1000, 2800, '你好世界']]);
    /* 关键：两条一被调开，isBilingualPair 立刻不认了，
       界面反而更看不出它们曾经是一对 —— 而那恰恰是最该提示的时候 */
    assert.strictEqual(SHF.isPairGroup(off, 0), true, '被调开的一对仍算一组');
    const seq = mk([[0, 2000, 'First sentence'], [2000, 4000, '第二句话']]);
    assert.strictEqual(SHF.isPairGroup(seq, 0), false, '正常流水不算一组');
    assert.strictEqual(SHF.isPairGroup(b, b.length - 1), false, '列表末尾不算一组');
  });

  t('v0.9.305：列表把一对串成一组，两条各自保留独立时间框', () => {
    const SH = readT('shift.html');
    assert.ok(/\.pg\{/.test(SH), '没有配对组的样式（左边那道竖线）');
    assert.ok(/isPairGroup\(list, i\)/.test(SH), 'renderList 没用 isPairGroup 分组');
    assert.ok(/function rowHtml\(/.test(SH), '行渲染没抽成函数');
    /* 两条各有一个起点 / 终点输入框 —— 分开调的自由度必须还在，别被「合并呈现」吃掉 */
    assert.ok(/data-s="' \+ i \+ '"/.test(SH), '行里没有起点输入框');
    assert.ok(/data-e="' \+ i \+ '"/.test(SH), '行里没有终点输入框');
    /* 一对的后一条不给合并按钮：它下面接的是下一句的原文，跨句拼起来没有意义 */
    assert.ok(/isBilingualMate\(list, i\)/.test(SH), '没拦住一对后一条的跨句合并');
    /* 一组要么整组渲染、要么都不渲染 —— 只画前一条会让人以为另一条丢了 */
    assert.ok(/html \+= pairHtml\(list, i, i \+ 1\); i \+= 2/.test(SH), '一组没整组渲染');
  });

  t('v0.9.305：不同轴提示 + 对齐按钮（后果说得清，退路给得到）', () => {
    const SH = readT('shift.html');
    assert.ok(/\.pnote\{/.test(SH), '没有提示行样式');
    assert.ok(/tpl\('msgUnalign'/.test(SH), '提示文案没走词典（写死中文，26 门语言看不懂）');
    assert.ok(/data-align="' \+ i \+ '"/.test(SH), '没有对齐按钮的绑定');
    assert.ok(/C\.alignOps\(S\.work, i\)/.test(SH), '对齐没走引擎的 alignOps');
    assert.ok(/if \(ops\) pushOp\(ops\)/.test(SH), 'alignOps 返回空时还硬推，会在 ops 里留个 null');
    /* 提示行用 warn 不用 del：字幕没坏，只是「这两条现在对不上」 */
    assert.ok(/\.pnote\{[^}]*--warn-weak/.test(SH), '提示行该用 warn 底色，不该用 del（红）');
  });

  t('v0.9.305：btnMergeOne / btnAlign / msgUnalign 三条 27 语齐全', () => {
    const vm2 = require('vm');
    const b2 = { window: {}, console: console }; b2.global = b2; vm2.createContext(b2);
    vm2.runInContext(readT('shift-i18n.js'), b2, { filename: 'shift-i18n.js' });
    const SI = b2.window.SHIFT_I18N;
    assert.ok(SI && SI.LANGS.length === 27, 'shift-i18n.js 没读出 27 语');
    const RE_HAN = /[\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]/;
    ['btnMergeOne', 'btnAlign', 'msgUnalign'].forEach(k => {
      SI.LANGS.forEach(([l]) => {
        const v = SI.DICT[l][k];
        assert.ok(typeof v === 'string' && v.length > 0, l + ' 缺 ' + k);
        if (k === 'msgUnalign') {
          assert.ok(v.indexOf('{0}') >= 0, l + ' 的 msgUnalign 丢了占位符：' + v);
        }
        if (!/^(zh-CN|zh-TW|ja)$/.test(l)) {
          assert.ok(!RE_HAN.test(v), l + ' 的 ' + k + ' 混进了汉字：' + v);
        }
      });
    });
    /* 老词条不能被注入脚本碰掉（每行插三个键，插错位会挤掉后面的） */
    SI.LANGS.forEach(([l]) => {
      ['btnMergeNext', 'btnSplit', 'btnUndo', 'chkBil'].forEach(k => {
        assert.ok(SI.DICT[l][k], l + ' 的老词条 ' + k + ' 被弄丢了');
      });
    });
  });

  t('v0.9.306：配对可见性 —— 305 那道淡紫竖线用户「没看出来」', () => {
    const SH = readT('shift.html');
    /* ⚠️ 这条测试的教训：305 写的是「有没有画那道线」，跑出来是绿的，
       用户打开一看什么都没有。**可见性不能用「属性存在」证明**，
       所以这里断言的是「够不够显眼」的三个具体量，浏览器那边另有 getComputedStyle 实测。 */
    assert.ok(/\.pg\{[^}]*background:var\(--acc-weak\)/.test(SH),
      '一对没有底色带（只靠一道竖线，白底上分不出哪两条是一组）');
    assert.ok(/\.pg\{[^}]*border-left:4px solid var\(--acc\)/.test(SH),
      '左条不是实心主色（305 用的 --acc-line 是最淡那档，等于没画）');
    assert.ok(!/border-left:3px solid var\(--acc-line\)/.test(SH),
      '305 那道看不见的淡紫竖线还在');
    assert.ok(/\.pg\{[^}]*border-radius:9px 0 0 9px/.test(SH), '色带没收口（看着像块脏底）');
    assert.ok(/\.pg \.li\{background:transparent\}/.test(SH),
      '行自己不透明，会把色带盖掉（等于还是没色带）');
    assert.ok(/\.pg \.li \+ \.li\{border-top:1px solid var\(--acc-line\)\}/.test(SH),
      '组内两条之间没有分隔线（分不清是两条还是一行）');
    /* ⚠️ 组与组必须断开：305 的竖线是满高的、组间只隔 1px 发丝线，
       三组连成一整条 → 反倒看不出分组 */
    assert.ok(/\.pg\{margin:6px 0;/.test(SH), '组与组之间没留间隙（竖线会连成一整条）');
    assert.ok(!/\.pg \+ \.pg, \.li \+ \.pg, \.pg \+ \.li\{border-top/.test(SH),
      '组间还在靠旧规则画发丝线');
  });

  t('v0.9.306：按钮护栏看 role，不许现算「当前还算不算一对」', () => {
    const SH = readT('shift.html');
    /* ⚠️ 305 的写法有个坑：后一条传 mate=-1，靠 isBilingualMate/isBilingualEntry 现判。
       两条一被调开超过 120ms 配对关系立刻不成立，护栏集体失效 ——
       译文行冒出「合并下一条」（点下去跨句拼的是下一句的原文）和「切分」
       （引擎 isBilingualEntry 拦着，点了没反应，看着像坏了）。恰恰是最该拦住的时候。 */
    assert.ok(/function rowHtml\(list, i, role\) \{/.test(SH),
      'rowHtml 还在用 mate 而不是 role（护栏会跟着配对关系一起失效）');
    assert.ok(/if \(role < 0 && !C\.isBilingualEntry\(list, i\)\) \{/.test(SH),
      '切分护栏没挂在 role 上');
    assert.ok(/else if \(role < 0 && !C\.isBilingualMate\(list, i\)\) \{/.test(SH),
      '合并护栏没挂在 role 上');
    assert.ok(/rowHtml\(list, i, 0\) \+ rowHtml\(list, mate, 1\)/.test(SH),
      '组头和组尾的 role 没传对（0/1）');
    assert.ok(/rowHtml\(list, i, -1\)/.test(SH), '独立行没传 role=-1');
    assert.ok(!/if \(!C\.isBilingualEntry\(list, i\)\) \{/.test(SH),
      '还有一处无条件的 isBilingualEntry 直判（会被调开状态骗过）');
  });

  t('v0.9.306：版号升到 306，shift 的两个缓存键跟着走', () => {
    const SH = readT('shift.html');
    assert.ok(/shift-core\.js\?v=0.9.406/.test(SH),
      'shift.html 的引擎缓存键没升（改了引擎不发版 = 老访客吃旧引擎）');
    assert.ok(/shift-i18n\.js\?v=0.9.406/.test(SH),
      'shift.html 的词典缓存键没升（改了词条不发版 = 老访客看键名）');
    assert.ok(/class="ver">v0\.9\.406/.test(readT('index.html')), '首页版号没升');
    assert.ok(/ver-tag">v0\.9\.406/.test(readT('translate.html')), '工作台版号没升');
    assert.ok(/class="ver">v0\.9\.406/.test(MERGE_SRC), 'merge.html 版号没升');
  });

  t('v0.9.304：版号升到 304，shift 的两个缓存键跟着走', () => {
    const SH = readT('shift.html');
    assert.ok(/shift-core\.js\?v=0.9.406/.test(SH),
      'shift.html 的引擎缓存键没升（改了引擎不发版 = 老访客吃旧引擎）');
    assert.ok(/shift-i18n\.js\?v=0.9.406/.test(SH),
      'shift.html 的词典缓存键没升（改了词条不发版 = 老访客看键名）');
    assert.ok(/class="ver">v0\.9\.406/.test(readT('index.html')), '首页版号没升');
    assert.ok(/ver-tag">v0\.9\.406/.test(readT('translate.html')), '工作台版号没升');
    assert.ok(/class="ver">v0\.9\.406/.test(MERGE_SRC), 'merge.html 版号没升');
  });

  /* ---------------- v0.9.308：六个垂直工具页的埋点 + 后台分 tab ----------------
     这一版的核心风险是**两处名单对不上**：页面上报的 page/act、服务端的白名单、
     后台的中文译名 —— 三处各写一遍，少对一次就是「用户明明用了，后台看不见」。
     所以断言不是各查各的，而是把三处拉到一起**交叉比对**。 */
  t('v0.9.308：六个垂直工具页都有埋点（纯前端页不埋点，后台永远没数据）', () => {
    const PAGES = ['shift', 'convert', 'extract', 'bilingual', 'repair', 'glossary'];
    PAGES.forEach(f => {
      const h = readT(f + '.html');
      assert.ok(/function reportTool\(/.test(h), f + ' 页没有 reportTool 定义');
      assert.ok(new RegExp("page: '" + f + "'").test(h), f + ' 页的 page 名与文件名对不上');
      assert.ok(/navigator\.sendBeacon\('\/api\/tool-event'/.test(h), f + ' 页没走 sendBeacon');
      assert.ok(/fetch\('\/api\/tool-event'/.test(h), f + ' 页没有 fetch 兜底（没有 sendBeacon 的浏览器就丢了）');
      /* 去重窗口：同一份内容反复点不该算多次 */
      assert.ok(/var TOOL_DEDUP_MS = \{/.test(h), f + ' 页没有去重窗口');
      /* ⚠️ 上报必须是 fire-and-forget：出错不许影响工具本身 */
      assert.ok(/catch \(err\) \{ \}/.test(h) || /\.catch\(function \(\) \{ \}\)/.test(h), f + ' 页上报没有兜住异常');
    });
  });

  t('v0.9.308：页面报的 act 与服务端白名单**双向**对得上（多一个少一个都算错）', () => {
    /* ⚠️ 解析白名单前先剥注释 —— 注释里有中文全角冒号还好，但英文单词配半角冒号会混进键名。
       ⚠️ 也不能按「行首」抓：白名单是一行塞好几个键（`edit: 'edit', apply: 'apply',`），
          按行首抓 TOOL_PAGE 只能抓到 2 个（307→308 实测踩过，报「不是六个」）。 */
    const keysOf = src => {
      const clean = String(src).replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '');
      return new Set((clean.match(/([a-zA-Z][a-zA-Z0-9]*)\s*:/g) || []).map(s => s.replace(/\s*:$/, '')));
    };
    const SRV = readT('server.js');
    const m = SRV.match(/const TOOL_ACT = \{[\s\S]*?\n\};/);
    assert.ok(m, 'server.js 里找不到 TOOL_ACT 白名单');
    const wl = keysOf(m[0]);
    assert.ok(wl.size >= 8, '白名单条目太少（六个页的动作应该都在），实际 ' + wl.size);
    const used = new Set();
    /* v0.9.316：埋点页扩到十二个；v0.9.321：再加 qc 共十三个
       （qc 的 check / fix 是本页独有的新动作，已同步进 TOOL_ACT 白名单）
       v0.9.356：补上 ytfix / autosub / ocrsub —— 前面漏登记的话，白名单里新加的
       动作（autosub 的 run）会被判成「页面从不发送」，反而误报 */
    ['shift', 'convert', 'extract', 'bilingual', 'repair', 'glossary',
     'videosub', 'hanconv', 'split', 'table', 'batch', 'lrc', 'qc',
     'ytfix', 'autosub', 'ocrsub'].forEach(f => {
      const h = readT(f + '.html');
      (h.match(/reportTool\([^\n]*?\{/g) || []).forEach(call => {
        (call.match(/'([a-zA-Z]+)'/g) || []).forEach(q => used.add(q.slice(1, -1)));
      });
    });
    used.delete('page');   /* reportTool 体内构造 body 时会带 page 字面量，不是动作 */
    const missing = [...used].filter(a => !wl.has(a));
    assert.deepStrictEqual(missing, [], '页面报了白名单里没有的动作（服务端会整条丢弃）：' + missing.join(','));
    const unused = [...wl].filter(a => !used.has(a));
    assert.deepStrictEqual(unused, [], '白名单里有页面从不发送的动作（注释写着「逐页对齐」就不该有）：' + unused.join(','));
  });

  /* v0.9.313：308 那会儿是六个页，加上 videosub / hanconv 共八个；
     v0.9.316：再加 split / table / batch / lrc 共十二个；v0.9.321：再加 qc 共十三个；
     后台中文译名同步补（不补的话表里直接甩 videosub 这种内部 id）。 */
  t('v0.9.308：八个页面名也在服务端白名单里，且后台有中文译名', () => {
    const keysOf = src => {
      const clean = String(src).replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '');
      return new Set((clean.match(/([a-zA-Z][a-zA-Z0-9]*)\s*:/g) || []).map(s => s.replace(/\s*:$/, '')));
    };
    const SRV = readT('server.js');
    const m = SRV.match(/const TOOL_PAGE = \{[\s\S]*?\n\};/);
    assert.ok(m, 'server.js 里找不到 TOOL_PAGE');
    const wl = keysOf(m[0]);
    /* v0.9.356：autosub / ocrsub 两页进账 → 16 条；v0.9.406：ktv 补登记 → 17 条 */
    assert.strictEqual(wl.size, 17, '页面白名单不是十七条，实际 ' + wl.size);
    const ADM = readT('admin.html');
    const tm = ADM.match(/const TL_PAGE_TXT = \{[\s\S]*?\n\};/);
    const am = ADM.match(/const TL_ACT_TXT = \{[\s\S]*?\n\};/);
    assert.ok(tm && am, '后台少了 TL_PAGE_TXT / TL_ACT_TXT 译名表');
    const pk = keysOf(tm[0]);
    assert.deepStrictEqual([...wl].filter(p => !pk.has(p)), [], '后台漏了页面译名（表格里会直接甩内部 id）');
    const am2 = SRV.match(/const TOOL_ACT = \{[\s\S]*?\n\};/);
    const ak = keysOf(am2[0]);
    const tk = keysOf(am[0]);
    assert.deepStrictEqual([...ak].filter(a => !tk.has(a)), [], '后台漏了动作译名');
  });

  t('v0.9.308：服务端两条路由齐（公网写 + 后台读），且写入口按白名单丢弃脏数据', () => {
    const SRV = readT('server.js');
    assert.ok(/u === '\/api\/tool-event'/.test(SRV), '少了公网上报路由 /api/tool-event');
    assert.ok(/u === '\/api\/admin\/tool-events'/.test(SRV), '少了后台读取路由 /api/admin/tool-events');
    assert.ok(/function appendTEvent\(/.test(SRV), '少了 appendTEvent');
    /* ⚠️ 这是这本账最关键的一道闸：page 或 act 对不上号就整条丢掉 */
    assert.ok(/if \(!page \|\| !act\) return;/.test(SRV),
      '写入口没有按白名单丢弃脏数据（认不出来的记录会污染统计）');
    assert.ok(/tool-events\.json/.test(SRV), '工具账没有自己的文件');
    /* 独立一本账，不与翻译/合并/清洗混 */
    assert.ok(!/appendTEvent[\s\S]{0,400}EVENTS_PATH/.test(SRV), '工具账写进了翻译那本账');
    /* 上报体积上限（与其它三条上报同一规格） */
    assert.ok(/u === '\/api\/tool-event'[\s\S]{0,200}readBody\(req, 4 \* 1024\)/.test(SRV), '上报没有限制请求体大小');
  });

