    const r2 = HCC.convertFile(crlf, 's2t', 'srt');
    if (r2.text.split('\r\n').length !== crlf.split('\r\n').length) throw new Error('行数变了');
    if (r2.text.indexOf('\n') >= 0 && r2.text.indexOf('\r\n') < 0) throw new Error('\\r\\n 被吃掉了');
