  const dict = ML_SRC.slice(iM, ML_SRC.indexOf('\n  };', iM));
  ["'zh-CN': {", "'zh-TW': {", "'en': {"].forEach(l => {
    assert.ok(dict.indexOf(l) > 0, 'MXT 缺语言块 ' + l + '（mxt() 只回落到 en，繁中访客会看到英文外壳）');
  });
