/* ============================================================================
   v0.9.392：rt=5（歌词缺词）隔离重译的纠错文案
   —— 387 摘掉语言跑偏检测后，badAnchor 只剩歌词缺号/丢词两类，可 rt=5 通道的纠错反馈
      仍写着「你上次的翻译语言跑偏了」。模型收到这句会去纠正语言，而真正的问题是少了一段
      歌词，改完照样缺段 —— 反馈把模型指向了错误的方向。
      391 起按 rt 分派：rt=5 → 歌词缺词语义；其余保留原文案（rt=4 的补救通道取组级 m.text，
      cue 对齐格式下恒为空，实际不触发，所以不动它的语义）。
   ============================================================================ */
console.log('\n— 纠错反馈文案按通道分派 —');

/* 把页面里那段 fb 构造块抽出来真跑，不是 grep 文案在不在 */
const fbOf = (f, feedback, rt, zhDst) => {
  const H = readT(f);
  const m = /const fb = \(Array\.isArray\(feedback\) && feedback\.length\)[\s\S]*?\n    : '';/.exec(H);
  assert.ok(m, f + '：抽不出 fb 构造块');
  const mk = new Function('feedback', 'rt', 'zhDst', 'dstN', m[0] + '\nreturn fb;');
  return mk(feedback, rt, zhDst, { zh: '日本語', prompt: 'Japanese' });
};

t('v0.9.392：rt=5 的反馈说的是「歌词缺词」，不是「语言跑偏」', () => {
  for (const f of ['translate.html', 'multilang.html']) {
    const H = readT(f);
    assert.strictEqual((H.match(/\? \(rt===5/g) || []).length, 1, f + '：fb 没有按 rt 分派');
    assert.strictEqual((H.match(/【歌词纠错】/g) || []).length, 1, f + '：中文歌词文案缺失');
    assert.strictEqual((H.match(/\[LYRIC RETRY\]/g) || []).length, 1, f + '：英文歌词文案缺失');

    const zh = fbOf(f, [{ no: null, text: '[1] 帰り道 [2] ' }], 5, true);
    assert.ok(/歌词纠错/.test(zh) && /分段编号/.test(zh), f + '：中文 rt=5 没走歌词文案');
    assert.ok(!/语言跑偏/.test(zh), f + '：中文 rt=5 仍在说语言跑偏');

    const en = fbOf(f, [{ no: null, text: '[1] on my way [2] ' }], 5, false);
    assert.ok(/LYRIC RETRY/.test(en) && /segment number/.test(en), f + '：英文 rt=5 没走歌词文案');
    assert.ok(!/wrong language/.test(en), f + '：英文 rt=5 仍在说语言跑偏');
  }
});

t('v0.9.392：其余通道的反馈文案原样保留，没被顺手改掉', () => {
  for (const f of ['translate.html', 'multilang.html']) {
    /* rt=4 补救通道：原文案语义保留 */
    const zh4 = fbOf(f, [{ gno: 3, text: 'x' }], 4, true);
    assert.ok(/纠错重试/.test(zh4) && /语言跑偏/.test(zh4), f + '：rt=4 的原有文案被改了');
    const en4 = fbOf(f, [{ gno: 3, text: 'x' }], 4, false);
    assert.ok(/CORRECTION RETRY/.test(en4), f + '：rt=4 英文原有文案被改了');
    /* rt 缺省（主批次）不能被误判成歌词通道 */
    const zh0 = fbOf(f, [{ no: 1, text: 'x' }], undefined, true);
    assert.ok(!/歌词纠错/.test(zh0), f + '：rt 缺省时误用了歌词文案');
    /* 没有反馈时必须是空串——不能凭空给模型塞一段纠错指令 */
    assert.strictEqual(fbOf(f, [], 5, true), '', f + '：feedback 为空却生成了纠错文案');
    assert.strictEqual(fbOf(f, null, 5, true), '', f + '：feedback 为 null 却生成了纠错文案');
  }
});

t('v0.9.392：歌词通道仍是「第 1 次带反馈、第 2 次盲发」', () => {
  for (const f of ['translate.html', 'multilang.html']) {
    const H = readT(f);
    assert.ok(/\(a===0&&badTexts\.length\)\?badTexts:null/.test(H),
      f + '：歌词通道的「第 1 次带反馈」判据不在了');
    assert.ok(/fbArr,ctx,5\)/.test(H), f + '：歌词通道没传 rt=5');
  }
});

t('v0.9.394：qc 页读速按 TTSG 收口，跟翻译页同一标准（不是英语 20 套所有语言）', () => {
  /* 用户问：「时长/读速这套标准，翻译页和质检页给的结论为什么不一样」。
     qc 的单位是「半角宽度/秒」（汉字·假名·谚文=2、拉丁=1、空格=1、组合记号=0），
     翻译页是「等效字/秒」（全角=1、半角=0.5、空格跳过）——折算回字符/秒才能对比。 */
  const box = { window: {}, console: console };
  box.global = box; require('vm').createContext(box);
  require('vm').runInContext(readT('qc-core.js'), box, { filename: 'qc-core.js' });
  const Q = box.QCCore || box.window.QCCore;
  assert.ok(Q && Q.paramsFor && Q.CPS_LANG, 'QCCore 没导出 CPS_LANG');

  /* 一、TTSG 在册语言的默认阈值（半角宽度/秒） */
  const TAB = { 'ja': 8, 'ko': 22, 'zh-CN': 18, 'zh-TW': 18, 'en': 20, 'ar': 20, 'hi': 18,
                /* 这 6 种原本被当成拉丁（一字一宽），实际每字符只有 0.81~0.86 宽 */
                'or': 14.0, 'mr': 14.6, 'ne': 14.3, 'bn': 14.5, 'as': 14.4, 'th': 13.8 };
  for (const k in TAB) {
    assert.strictEqual(Q.paramsFor(k).maxCpsW, TAB[k], k + ' 的读速阈值不是 ' + TAB[k]);
  }

  /* 二、折回「TTSG 字符/秒」必须落在 ±10% 内。每字占多少宽度是实测的
        （_chk-qc-cps.js：汉字 1.90 · 谚文 1.98 · 天城文 0.83 · 拉丁/阿拉伯 1.00） */
  const TTSG = {
    'ja': [4, 1.90], 'ko': [12, 1.98], 'zh-CN': [9, 1.90],
    'en': [20, 1.00], 'ar': [20, 1.00], 'hi': [22, 0.83],
    /* 不在 TTSG 分册里，按「其他 17」：17 × 实测每字符宽度 */
    'or': [17, 0.82], 'mr': [17, 0.86], 'ne': [17, 0.84],
    'bn': [17, 0.85], 'as': [17, 0.85], 'th': [17, 0.81]
  };
  for (const k in TTSG) {
    const cps = Q.paramsFor(k).maxCpsW / TTSG[k][1];
    const dev = Math.abs(cps - TTSG[k][0]) / TTSG[k][0];
    assert.ok(dev <= 0.10, k + ' 折算回字符/秒是 ' + cps.toFixed(1) +
      '，TTSG 是 ' + TTSG[k][0] + '（偏差 ' + (dev * 100).toFixed(0) + '%）');
  }

  /* 三、之前的两处硬伤不许回来：日文跟着中文同档（松 2.2 倍）、非英语拉丁语系按 20（松 15%） */
  assert.strictEqual(Q.DEF.lat.maxCpsW, 17, '拉丁档不是 TTSG 的「其他 17」');
  assert.notStrictEqual(Q.paramsFor('ja').maxCpsW, Q.paramsFor('zh-CN').maxCpsW,
    '日文又跟中文同档了（TTSG：日文 4 全角字/秒，中文 9）');
  assert.strictEqual(Q.paramsFor('de').maxCpsW, 17, '德语（TTSG 17）没落在拉丁档');
  assert.strictEqual(Q.paramsFor('yue').maxCpsW, 18, '粤语写汉字，读速应跟中文同档');

  /* 四、读速不随画面方向变；认不出的语码落回拉丁档且不抛异常 */
  ['land', 'square', 'port'].forEach(function (fr) {
    assert.strictEqual(Q.paramsFor('ja', fr).maxCpsW, 8, fr + ' 改了日文读速');
    assert.strictEqual(Q.paramsFor('en', fr).maxCpsW, 20, fr + ' 改了英文读速');
  });
  assert.strictEqual(Q.paramsFor('xx-unknown').maxCpsW, 17, '未知语码没落回 17');

  /* 五、页面输入框仍然能盖过默认值 —— 改的是默认值，不是把阈值写死 */
  const r = Q.check([{ i: 1, st: 0, en: 1000, tx: ['あ'.repeat(12)] }], { lang: 'ja', maxCpsW: 40 });
  assert.strictEqual(r.issues.filter(x => x.r === 'rCps').length, 0, '页面传进来的 maxCpsW 没生效');
});

t('v0.9.394：裸引用的 id 必须在 DOM 里 —— 393 删按钮删出的血案', () => {
  /* 真实事故：v0.9.393 把抽屉连同顶栏三个按钮一起删了（设置 / 下载全部 / 上传新字幕），
     连「导入字幕」区的「📂 选择字幕文件」也一并消失。但 JS 里这三处绑定一个都没删：
         $('btnFile').addEventListener('click', ...)              ← 没有判空
         document.getElementById('btnUploadNew').addEventListener(...) ← 没有判空
     浏览器执行到第一行就抛 TypeError，**整段内联脚本从此中断** —— 卡片点不开、
     切语言不换标题、下载全部没反应，而页面看起来完全正常（静态 DOM 都在）。
     静态测试查不出来（只查文本不跑 DOM），只有真浏览器才暴露。

     规则：`$('x').方法()` / `getElementById('x').方法()` 这种**不带判空的裸引用**，
     对应的 id 必须真的存在于 DOM。带判空的（if (el) / && / if (!el) return）不在此列，
     因为运行时动态创建的元素本来就不写死在 HTML 里（errModal / mlConfirm 之类）。 */
  const FILES = ['multilang.html', 'translate.html', 'index.html', 'merge.html', 'qc.html',
                 'batch.html', 'bilingual.html', 'autosub.html', 'convert.html', 'split.html'];
  const bad = [];
  FILES.forEach(f => {
    const src = readT(f);
    if (!src) return;
    const dom = new Set([...src.matchAll(/\bid="([A-Za-z][\w-]*)"/g)].map(m => m[1]));
    for (const m of src.matchAll(/\$\('([A-Za-z][\w-]*)'\)\./g)) {
      if (!dom.has(m[1])) bad.push(f + ':' + m[1]);
    }
    for (const m of src.matchAll(/getElementById\('([A-Za-z][\w-]*)'\)\./g)) {
      if (!dom.has(m[1])) bad.push(f + ':' + m[1]);
    }
  });
  assert.strictEqual(bad.length, 0,
    '这些 id 被裸引用（$(\'x\').xxx 没判空）但 DOM 里没有，浏览器会抛 TypeError 中断整段脚本：' +
    [...new Set(bad)].join(', '));
});

t('v0.9.395：姊妹页共用的顶层常量，本页引用了就必须有定义 —— BUILTIN_API 血案', () => {
  /* 真实事故（比上面那条 id 的更隐蔽）：v0.9.394 重构术语表卡片时，multilang.html 里的
         const BUILTIN_API = '/api/translate';
     连同上头 3 行注释一起被误删（紧跟其后的 RELAY_API 完好无损，所以肉眼看不出缺东西）。
     translate.html 有自己的定义，所以单语页一直正常；多语页一跑内置通道就在
         async function chatOnce(...){ const builtin = (base===BUILTIN_API); ...
     第一行抛 ReferenceError。更糟的是外层 catch 只记一行「发生错误」，
     任务照样标记「✓ 完成（81 条）」—— 用户下载到的是没翻译的字幕。

     为什么静态测试之前查不出来：new Function() 只能验语法，未定义标识符是运行时才炸。
     规则：两页是手抄副本、不共用 js，所以 translate.html 顶层声明的全大写常量，
     只要 multilang.html 里出现了这个名字，就必须在 multilang.html 里也有 const/let/var。
     反过来的方向不查——多语页允许有自己独有的常量（MXT、ML 之类）。 */
  const tSrc = readT('translate.html'), mSrc = readT('multilang.html');
  assert.ok(tSrc && mSrc, '读不到 translate.html / multilang.html');
  const declRe = /\b(?:const|let|var)\s+([A-Z][A-Z0-9_]{2,})\s*=/g;
  const tDecl = new Set([...tSrc.matchAll(declRe)].map(m => m[1]));
  const mDecl = new Set([...mSrc.matchAll(declRe)].map(m => m[1]));
  const missing = [...tDecl].filter(k => !mDecl.has(k) && new RegExp('\\b' + k + '\\b').test(mSrc));
  assert.strictEqual(missing.length, 0,
    'multilang.html 用了 translate.html 才有的常量，运行时必抛 ReferenceError：' + missing.join(', '));
  /* 这两条是内置通道的命门，单独钉死：定义必须在、引用也必须在（定义被挪走同样致命） */
  assert.ok(/const BUILTIN_API = '\/api\/translate'/.test(mSrc), 'multilang.html 丢了内置通道端点常量');
  assert.ok(/const RELAY_API =/.test(mSrc), 'multilang.html 丢了服务端转发端点常量');
});

t('v0.9.396：空译文快照必须作废 —— 394 事故的次生伤害', () => {
  /* 394 那批「内置通道全线报错」期间，每批都失败被跳过，但批次计数照样推进、
     整片跑完 fin 照样置位 → 快照记成「已完成 · 零译文」。
     而多语队列的 askReuse 是静默的（if(S.multi) return Promise.resolve('reuse')），
     用户重跑同一份字幕会零请求秒完成、拿到原文，症状比原来更迷惑。
     所以 loadSnap 必须自己判：done 里一条非空译文都没有 → 删掉、当没快照。 */
  const src = readT('multilang.html');
  /* v0.9.397：判据抽成了 snapHasText(o)，且必须逐条看 cueTexts 的内容
     （396 只看条目数，放行了 cueTexts:[[1,''],[2,'']] 这种「编号齐全、译文全空」的形态）。
     这条用例只锁「空快照不许复用」这个意图，实现细节由 v0.9.397 那条更严的用例盯。 */
  /* v0.9.404：判据的实现下沉到 snap-store.js（翻译页此前压根没有这道闸，现在两页共用一份）。
     本页保留的 snapHasText(o) 只是个转发，供 mlSnapInfo 等处调用。 */
  assert.ok(/function snapHasText\(o\)\{ return SnapStore\.snapHasText\(o\); \}/.test(src),
    '缺 snapHasText：判断快照里到底有没有译文');
  assert.ok(/function snapHasText\(o\)\{/.test(SNAP_SRC), 'snap-store.js 里没有判据实现');
  assert.ok(/if\(!usable\(o\)\)\{ dropKey\(key\); return null; \}/.test(SNAP_SRC),
    '空译文快照没有被作废（会被当成已完成结果静默复用）');
  assert.ok(/if\(!snapHasText\(o\)\) return false;/.test(SNAP_SRC),
    'usable 没调用 snapHasText（空快照会被放行）');
  /* 这条防护的前提是多语队列「不弹窗直接取回」。若将来给多语也加了弹窗，
     本防护仍然有益，但需要重新评估提示语与默认值 —— 断言会提醒。 */
  assert.ok(/if\(S\.multi\) return Promise\.resolve\('reuse'\)/.test(src),
    '多语队列的静默复用行为变了，请重新评估 v0.9.396 这条空快照防护');
});

t('v0.9.397：有历史任务必须先问（继续 / 重新 / 取消），且空译文快照不算历史', () => {
  /* 用户反馈原话：
     「上传字幕，点击开始翻译后，如果里面有历史任务，会直接死掉，没有之前那个弹窗
       任务告诉用户应该继续翻译或者重新翻译，或者使用上一次结果」
     「但我刚才开始翻译任务后，直接显示完成，下载后确是空」
     两个现象同一个根因：多语队列的 askReuse 是静默的（if(S.multi) return 'reuse'），
     点开始后一个请求都不发、一秒全「完成」，弹窗还写着「约 0 批」；
     而 394 事故留下的坏快照（done 结构完整、cueTexts 编号齐全但译文全是空串）
     被 396 的「只数条目数」判据放行，于是复用它 → 下载出来是空白字幕。 */
  const src = readT('multilang.html');

  /* 一、判据必须逐条看 cueTexts 的内容，不能只判 length（396 就栽在这） */
  /* v0.9.404：判据实现在 snap-store.js（两页共用），页面里只保留转发与调用点。 */
  assert.ok(/function snapHasText\(o\)\{/.test(SNAP_SRC), '缺 snapHasText：快照有没有真译文的唯一判据');
  assert.ok(/String\(p\[1\] == null \? '' : p\[1\]\)\.trim\(\)/.test(SNAP_SRC),
    'snapHasText 没逐条检查 cueTexts 的译文内容（只判 length 会把全空串当成有效结果）');
  assert.ok(/if\(!usable\(o\)\)\{ dropKey\(key\); return null; \}/.test(SNAP_SRC),
    'loadSnap 没有用 snapHasText 作废空快照');
  assert.ok(/if\(!snapHasText\(o\)\) return null;/.test(src),
    'mlSnapInfo 没跟 loadSnap 用同一判据（界面说「已完成」而引擎会作废，两边会互相打脸）');

  /* 二、开跑前必须问。以前 savedTasks/savedBatches 只用来算「约 0 批」，不让用户选 */
  assert.ok(/function mlHistStat\(tasks\)/.test(src), '缺 mlHistStat：开跑前的历史统计');
  assert.ok(/function mlDropSnaps\(cells\)/.test(src), '缺 mlDropSnaps：选「重新翻译」时得真删快照');
  assert.ok(/var hist = mlHistStat\(tasks\);/.test(src), 'runMulti 开跑前没有统计历史任务');
  assert.ok(/mlt\(hist\.partN > 0 \? 'histBody' : 'histBodyDone'/.test(src),
    '确认弹窗没按「全译完 / 还有未完成」分别措辞');
  assert.ok(/goOn === 'extra'/.test(src) && /mlDropSnaps\(hist\.cells\)/.test(src),
    '选了「全部重新翻译」却没清快照（引擎内部仍会静默复用旧结果）');

  /* 三、mlConfirm 要支持第三个按钮，且旧的两按钮调用语义不变 */
  assert.ok(/function mlConfirm\(title, body, note, okTxt, cancelTxt, extraTxt\)/.test(src),
    'mlConfirm 没加 extraTxt 参数');
  assert.ok(/if\(extraTxt\) mk\(extraTxt, false, 'extra'\);/.test(src), 'extraTxt 按钮没渲染');
  assert.ok(/mk\(okTxt, true, 'ok'\);/.test(src), '主按钮返回值不是 ok');

  /* 四、12 种界面语言都要有这套文案，少一种就会退回英文或露出 key */
  const NEED = ['histTitle', 'histBody', 'histBodyDone', 'histNote', 'histResume', 'histRedo', 'histCancel', 'histRedoLog'];
  for (const k of NEED) {
    const n = (src.match(new RegExp('\\b' + k + ':', 'g')) || []).length;
    assert.ok(n >= 12, '词条 ' + k + ' 只出现在 ' + n + ' 种界面语言里（应为 12）');
  }
});

t('v0.9.398：自定义风格没填必须弹窗引导，且不许把「没跑」记成「完成」', () => {
  /* 用户原话：
     「如果用户在翻译风格中选择了自定义风格，但没填写内容，也不弹窗引导用户去填写，
       而是直接卡住（同时多语的时候却报成功）。这个在翻译和多语都需要处理」
     两条根因：
       ① 两页的校验都只有 log(t('customNeed')) + return —— 按钮闪一下就恢复，
          日志滚在页面下方，用户侧就是「点了没反应」；
       ② 多语队列拿 S.rows.length 判成功，而 S.rows 在 mlUseFile 里就被原文填满
          （zh 全是 null），早退也被记成「✓ 完成」，最后「全部完成」但每格是原文。 */
  const tr = readT('translate.html'), ml = readT('multilang.html');

  /* 一、两页都要有统一体检 + 三选一引导 */
  for (const [name, src] of [['translate.html', tr], ['multilang.html', ml]]) {
    assert.ok(/function preflightCfg\(cfg\)/.test(src), name + ' 缺 preflightCfg（体检入口）');
    assert.ok(/code:'customEmpty'/.test(src), name + ' 没把「自定义风格为空」当成需要拦的问题');
  }
  assert.ok(/async function preflightGuard\(\)/.test(tr), '单语页缺 preflightGuard');
  assert.ok(/async function preflightAsk\(pf\)/.test(ml), '多语页缺 preflightAsk');
  assert.ok(/if\(!\(await preflightGuard\(\)\)\) return false;/.test(tr),
    '单语页 runTranslate 还是只 log 不拦（用户会觉得点了没反应）');
  assert.ok(/await mlConfirm\(mlt\('pfStyleTitle'\)/.test(ml.replace(/\s+/g, ' ')),
    '多语页没有弹「还差一步」的三选一');

  /* 二、多语页必须在任务循环之前统一拦一次，而不是每格各失败一遍 */
  const iLoop = ml.indexOf('for(var i=0;i<total;i++){');
  const iPf = ml.indexOf("var pf = preflightCfg(getCfg());");
  assert.ok(iPf > 0 && iPf < iLoop, '体检没排在队列循环之前（会每格弹一次 / 每格假成功）');
  assert.ok(/if\(pfAct !== 'go'\) return;/.test(ml), '体检失败后没有中止队列');

  /* 三、成功判据不能再看 S.rows.length */
  assert.ok(/var okZh = !!\(S\.rows && S\.rows\.length && S\.rows\.some\(/.test(ml),
    '多语页没要求「至少一条真译文」（S.rows 里原文行会让空跑也算成功）');
  assert.ok(!/if\(S\.rows && S\.rows\.length\)\{/.test(ml),
    '成功判据又退回 S.rows.length 了 —— 原文行也算数，空跑会被记成完成');

  /* 四、点「去填写」要能把折叠卡片展开并聚焦（卡片收着时输入框根本看不见） */
  /* v0.9.398：这里不能用 cfgToggle —— 它长在 IIFE 里，preflightAsk 在外层，
     直接调用会抛 ReferenceError 被 catch 吞掉（实测「去填写」点了没反应）。
     所以直接加 class + 同步 aria。 */
  assert.ok(/card\.classList\.add\('open'\)/.test(ml) && /cfgTransHd/.test(ml),
    '多语页没展开翻译设置卡片');
  assert.ok(/box\.scrollIntoView\(\{ behavior:'smooth', block:'center' \}\)/.test(ml),
    '没有滚动到输入框');
  assert.ok(/box\.focus\(\); box\.select\(\);/.test(ml), '没有聚焦并选中输入框');

  /* 五、摘要上要标出来，别等点开始才拦 */
  assert.ok(/sLab \+= mlt\('styleEmptyTag'\)/.test(ml), '卡片摘要没标「未填写」');

  /* 六、词条：单语页 27 语 × 4 条，多语页 12 语 × 8 条 */
  const i18n = readT('site-i18n.js');
  for (const k of ['pfStyleTitle', 'pfGoFill', 'pfUseDefault', 'pfSwitched']) {
    const n = (i18n.match(new RegExp('\\b' + k + ':', 'g')) || []).length;
    assert.ok(n >= 27, 'site-i18n 的 ' + k + ' 只有 ' + n + ' 种语言（应为 27）');
  }
  for (const k of ['pfStyleTitle', 'pfGoFill', 'pfUseDefault', 'pfSwitched', 'pfNoResult', 'styleEmptyTag']) {
    const n = (ml.match(new RegExp('\\b' + k + ':', 'g')) || []).length;
    assert.ok(n >= 12, 'MLT 的 ' + k + ' 只有 ' + n + ' 种语言（应为 12）');
  }
});

t('v0.9.399：任务矩阵的「N 条」不能去数导出文本里的箭头', () => {
  /* 用户截图：翻译完成后 2×2 四个格子全是「✓ 完成 · 0 条」，可下载内容是好的。
     根因：mxCount() 数的是导出文本里 "-->" 的个数，而 ASS / SBV / TXT 三种格式
     根本没有箭头（ASS 是 Dialogue: 行，SBV 是逗号，TXT 是纯文本）——
     只要导出格式不是 SRT/VTT，整张矩阵就全变 0 条，看着像没翻出来。
     条数应该来自这一格实际排出来的行数 res.rows（v0.9.392 起每格都存了）。 */
  const ml = readT('multilang.html');
  assert.ok(/var cnt = Array\.isArray\(res\.rows\) \? res\.rows\.length : mxCount\(res\.text\)/.test(ml),
    '矩阵条数没有优先用 res.rows.length（导出格式一换就会变 0）');
  assert.ok(!/meta2 = mxCount\(res\.text\) \+ ' 条'/.test(ml),
    '又回去数 --> 了：ASS/SBV/TXT 下会显示 0 条');
  /* 折行切分会让「导出行数」多于「原文条数」，悬停要说明白，别让用户以为算错了 */
  assert.ok(/if\(res && cnt !== f\.items\.length\) mxTip \+=/.test(ml),
    '导出行数与原文条数不一致时没有说明');
});

/* ============================================================================
   v0.9.400：日志不再「一重试一行」，事件不再把长任务切成多条
   —— 用户原话：「管理后台看到的统计应该是用户点击开始翻译，就是一条记录。
      系统自动重试的不要产出太多记录，不然太乱。」
   此前两处都违反这条：
     · 整批重发每失败一次打一行错误（3 次重试 + 拆组补救 + 补译，一次任务刷二十多行）；
     · 带任务号的记录仍按 30 分钟窗口归并，大文件跑过半小时就另起一条
       （10-27 实证：10395 条的任务被切成 07:47 / 08:17 / 08:47 三条，看着像点了三次）。
   ============================================================================ */
console.log('\n— v0.9.400 日志压缩 / 事件按任务合并 —');

t('v0.9.400：重发失败不再逐次打行，同一批恒定一行', () => {
  for (const f of ['translate.html', 'multilang.html']) {
    const s = readT(f);
    assert.ok(/const _stickyMap = new Map\(\);/.test(s), f + ' 缺 _stickyMap');
    assert.ok(/function logSticky\(key, msg, cls\)\{/.test(s), f + ' 缺 logSticky');
    assert.ok(/function logStickyEnd\(key\)\{ _stickyMap\.delete\(key\); \}/.test(s), f + ' 缺 logStickyEnd');
    /* 一个批的「发出 → 失败 → 完成」必须共用同一个 key，否则照样一行一条 */
    assert.ok(/logSticky\('b'\+batchNo\+'-'\+\(\(rt===6\|\|!rt\)\?0:rt\), t\('reqSent'/.test(s),
      f + ' 「请求已发出」没走 sticky 或没把 rt=6 归到主通道（重发时每轮都会多一行）');
    assert.ok(s.indexOf("logSticky('b'+(bi+1)+'-0', t('batchFail',bi+1,attempt+1,e.message),'err')") > 0,
      f + ' 批失败没走 sticky，会一行一条');
    assert.ok(/logSticky\('b'\+\(bi\+1\)\+'-0', t\('batchDone'[\s\S]{0,140}logStickyEnd\('b'\+\(bi\+1\)\+'-0'\);/.test(s),
      f + ' 批完成没有收尾，下一批会覆盖这一行');
    assert.ok(!/logSticky\(t\('batchFail',bi\+1,attempt\+1/.test(s), f + ' 还有没带 key 的 batchFail');
    assert.ok(/function clearLog\(\)\{ \$\('log'\)\.innerHTML = ''; _stickyMap\.clear\(\); \}/.test(s),
      f + ' clearLog 没清 sticky 表（换文件后会往旧行里写）');
  }
});

t('v0.9.400：心跳从 30 秒推到 90 秒，停止按钮仍 30 秒放开', () => {
  for (const f of ['translate.html', 'multilang.html']) {
    const s = readT(f);
    assert.ok(/\}, 90000\);/.test(s), f + ' 心跳没推到 90 秒');
    assert.ok(/const hbZ=setTimeout\(\(\)=>\{ try\{ var b=\$\('btnGo'\); if\(b\) b\.disabled=false; \}catch\(e\)\{\} \}, 30000\);/.test(s),
      f + ' 停止按钮的 30 秒放开被一起改掉（平台不回话时用户就停不下来了）');
    assert.ok(/clearTimeout\(hbT\); clearTimeout\(hbZ\);/.test(s), f + ' 新定时器没在 finally 里清掉');
  }
});

t('v0.9.400：整批重发单独记 retryBatch，不再冒充 batches', () => {
  const S = readT('server.js');
  const m = /const RT_FIELD = (\{[^\n]*\});/.exec(S);
  assert.ok(m, 'server.js 里找不到 RT_FIELD');
  const map = new Function('return ' + m[1] + ';')();
  assert.strictEqual(map['6'], 'retryBatch', 'rt=6 没映射到 retryBatch');
  [['1', 'retryMusic'], ['2', 'retryAnchor'], ['3', 'retryCue'], ['4', 'retryRescue'], ['5', 'retryLyric']]
    .forEach(([k, v]) => assert.strictEqual(map[k], v, 'rt=' + k + ' 被误改'));
  /* v0.9.403：translate.html 的主通道改成「首批 rt=0 + 拆半各 rt=6」，
     写法从 attempt?6:0 变成两个显式常量，判据随之下沉到两个调用点；
     multilang.html 未跟进（多语言页仍走整批重发），两页判据因此分开。 */
  const T = readT('translate.html');
  assert.ok(/totalB,sysB,null,ctx,0\)/.test(T), 'translate.html 首批没带 rt=0');
  assert.ok(/totalB,sysB,null,ctx,6\)/.test(T), 'translate.html 重发没带 rt=6');
  assert.ok(!/totalB,sysB,null,ctx, attempt\?6:0\)/.test(T), 'translate.html 还留着旧的 attempt?6:0 写法');
  assert.ok(/totalB,sysB,null,ctx, attempt\?6:0\)/.test(readT('multilang.html')), 'multilang.html 主通道重发没带 rt=6');
});

t('v0.9.400：同一任务号不再被 30 分钟窗口切成多条', () => {
  const S = readT('server.js');
  assert.ok(/const EVENT_TASK_MS = 12 \* 60 \* 60 \* 1000;/.test(S), '缺 EVENT_TASK_MS');
  assert.ok(/const win = f\.task \? EVENT_TASK_MS : EVENT_DEDUP_MS;/.test(S), '窗口没按任务号分流');
  assert.ok(/if \(evHit\(e, ip, f\) && now - e\.t < win\) \{/.test(S), '命中判定没用 win');
  assert.ok(/if \(now - e\.t >= win\) break;/.test(S), '提前退出没用 win');
  /* 没有任务号的老页面仍是 30 分钟窗口 —— 这条不能被顺带改掉 */
  assert.ok(/const EVENT_DEDUP_MS = 30 \* 60 \* 1000;/.test(S), '老口径的 30 分钟窗口被改掉了');
});

t('v0.9.400：版号与缓存 bust 五处一致', () => {
  const idx = readT('index.html'), tr = readT('translate.html');
  assert.ok(/const ASSET_VER = '0\.9\.406';/.test(readT('server.js')), 'ASSET_VER 未升');
  assert.ok(/class="ver-tag">v0\.9\.406</.test(readT('translate.html')), '工作台版号未升');
  assert.ok(/class="ver">v0\.9\.406</.test(idx), '首页版号未升');
  assert.ok(/srt-core\.js\?v=0\.9\.406/.test(tr), '工作台 srt-core 缓存 bust 未升');
  assert.ok(/site-i18n\.js\?v=0\.9\.406/.test(idx), '首页 site-i18n 缓存 bust 未升');
});

/* ============================================================================
   2026-10-27 / v0.9.403：整批重发改「拆半重发」
   —— 原来 attempt 1、2 的请求体逐字节相同（sysB / ctx / feedback 全不变），
      只对网络抖动、上游返空这类偶发失败有效；对「模型稳定地这么输出」零效果。
      线上实测（10-27 全天）retryBatch 只触发 18 次 / 2041 批，六条通道里最少，
      且这 18 次全是「再抽一次同样的签」。
      改成：第 1 次整批（rt=0），第 2 次把本批一分为二各发一次（各 rt=6）。
      请求数不变（1 整批 + 2 半批 = 3），每次规模减半。
   ============================================================================ */
t('v0.9.403：整批重发改拆半，两半各带 rt=6', () => {
  const T = readT('translate.html');
  assert.ok(/const maxTry  = 2;/.test(T), 'maxTry 没降为 2（拆半后不再需要第 3 次整批）');
  assert.ok(/const mid=Math\.ceil\(gBatch\.length\/2\);/.test(T), '缺拆半点');
  assert.ok(/\[gBatch\.slice\(0,mid\), gBatch\.slice\(mid\)\]\.filter\(h=>h\.length>0\)/.test(T), '切分写法被改（空半批必须被滤掉）');
  /* 两半串行、且在 S.stop 处可停：并发会让用户点停后还有人继续压上游 */
  assert.ok(/for\(const h of halves\)\{\n\s*if\(S\.stop\) break;/.test(T), '两半之间没有 S.stop 检查');
  /* 两半全败 → 抛出去走逐组补救；一成一败 → 先落库成功那半，再抛 */
  assert.ok(/if\(!acc\) throw halfErr \|\| new Error\('half retry failed'\)/.test(T), '两半全败没有抛出');
  /* 排队超时必须就地停：外层的 S.stop 要等这轮拆半跑完才置位，那之前第二半已经发出去了 */
  assert.ok(/if\(e2 && e2\.paceGiveUp\)\{ S\.paceOut=true; S\.stop=true; break; \}/.test(T), '拆半途中遇到排队超时没停');
  /* 分支行为由 test-half.js 覆盖（async，塞不进本文件的同步 t()） */
  assert.ok(/const skip=new Set\(acc\.badAnchor\|\|\[\]\);/.test(T), '一成一败时没剔出待救援组');
  assert.ok(/throw halfErr;/.test(T), '一成一败没有抛给补救通道');
  /* 剔出范围必须覆盖四类专用通道，漏一类就会带着 drop / 结构错过关 */
  ['cueBadGnos', 'musicDropGnos', 'subDropGnos'].forEach(k => {
    assert.ok(new RegExp('\\(acc\\.' + k + '\\|\\|\\[\\]\\)\\.forEach').test(T), '一成一败时没剔出 ' + k);
  });
  /* 首批必须是整批、rt=0；只有 attempt>=1 才拆 */
  assert.ok(/if\(attempt===0\)\{\n\s*out=await translateBatch\(effBase,effKey,effModel,gBatch,bi\+1,totalB,sysB,null,ctx,0\);/.test(T), '首批不再是整批 rt=0');
});

t('v0.9.403：mergeBatchOut 合并两半结果，fillers 去重且仍是 Set', () => {
  const T = readT('translate.html');
  const m = /function mergeBatchOut\(a,b\)\{[\s\S]*?\n\}/.exec(T);
  assert.ok(m, '找不到 mergeBatchOut');
  const merge = new Function('return ' + m[0])();
  const a = {
    byGno: { 1: { text: 'a1' }, 2: { text: 'a2' } }, fillers: new Set([3, 4]),
    badAnchor: [1], musicDropGnos: [2], subDropGnos: [], cueBadGnos: [{ gno: 2, errs: ['e'] }],
    thinN: 5, thinSample: [{ g: 1 }],
  };
  const b = {
    byGno: { 3: { text: 'b3' } }, fillers: new Set([4, 5]),
    badAnchor: [3], musicDropGnos: [], subDropGnos: [2], cueBadGnos: [],
    thinN: 7, thinSample: [{ g: 3 }],
  };
  const r = merge(a, b);
  assert.deepStrictEqual(Object.keys(r.byGno).sort(), ['1', '2', '3'], 'byGno 没并全');
  /* fillers 是 Set：外层直接 .forEach 消费，类型退化成数组虽也能跑，但 set.size / has 会静默失效 */
  assert.ok(r.fillers instanceof Set, 'fillers 不再是 Set');
  assert.deepStrictEqual([...r.fillers].sort((x, y) => x - y), [3, 4, 5], 'fillers 没去重或丢了');
  assert.deepStrictEqual(r.badAnchor, [1, 3], 'badAnchor 丢失');
  assert.deepStrictEqual(r.musicDropGnos, [2], 'musicDropGnos 丢失');
  assert.deepStrictEqual(r.subDropGnos, [2], 'subDropGnos 丢失');
  assert.strictEqual(r.cueBadGnos.length, 1, 'cueBadGnos 丢失');
  assert.strictEqual(r.thinN, 12, 'thinN 没累加');
  assert.strictEqual(r.thinSample.length, 2, 'thinSample 丢失');
  /* 任一侧为空时原样返回，不能把先成功的那半吞掉 */
  assert.strictEqual(merge(null, b), b, 'a 为空时没返回 b');
  assert.strictEqual(merge(a, null), a, 'b 为空时没返回 a');
});

/* ============================================================================
   2026-10-27：后台「槽」列一律显示批次数（含 ×1）
   —— 用户原话：「很多数据有槽的名称，但没请求次数」。查下来不是统计缺失：
      数据里 sbD=1 是存着的，只是渲染时把「单槽单批」的 ×1 省了。
      这属于后台显示口径，只改 admin.html（该页没有版号、服务端 no-cache），
      所以公共页面版号仍是 v0.9.400，这里也不用跟版号断言。
   ============================================================================ */
console.log('\n— 后台槽列：批次一律显示 —');

t('后台槽列：单批也标 ×N，旧记录不许谎报', () => {
  const a = readT('admin.html');
  assert.ok(/function slotCell\(e\)\{/.test(a), 'admin.html 找不到 slotCell');
  /* 精确计数一律带 ×N（含 ×1）—— 用户 10-27 点名要的 */
  assert.ok(/const exact = e\.slotExact === 1;/.test(a), '槽列没有区分精确计数与旧记录');
  assert.ok(/\(exact \? '<span class="slotn">×' \+ x\.n \+ '<\/span>' : ''\)/.test(a),
    '槽列的 ×N 没有按 exact 渲染');
  assert.ok(!/x\.n > 1 \|\| mix\.length > 1 \?/.test(a),
    '还留着「多批才显示 ×N」的旧条件——单批会退回只有字母');
  /* 自带 Key / 早期记录两条兜底不能被顺手改掉 */
  assert.ok(/if \(e\.byok\) return '<span class="slot slotByok"/.test(a), '自带 Key 的槽显示丢了');
  assert.ok(/if \(!mix\.length\) return '<span style="color:var\(--mut\)"/.test(a), '早期无标记记录该显示「-」');
  /* 旧记录的 n 恒为 1（只知道最后一批），写成 ×1 就是谎报 */
  assert.ok(/看不出中途是否换过/.test(a), '旧记录的 tooltip 说明丢了');
});

/* ============================================================================
   v0.9.401：多语批量页的下载拆成「选中 / 全部」两键 + 任务之间空 5 秒
   —— 用户原话：「下载字幕这里分为：下载选中字幕、下载全部字幕」
      「只要任务矩阵中有任务已经翻译完成，就可以支持用户下载」「下载打点要全面」
      「每个字幕任务之间应该等待 5 秒再加入后台队列」

   改造前那个单键有三种含义（结果 >1 打 zip、==1 下单个、==0 落到编辑器内容），
   点下去之前不知道会拿到什么；而「只想拿这一格」时被迫连整季一起下。
   ============================================================================ */
console.log('\n— v0.9.401 下载两键 / 任务间隔 —');

t('v0.9.401：多语页下载拆成「选中 / 全部」两键', () => {
  const m = readT('multilang.html');
  assert.ok(/id="btnDownload"[^>]*data-i18n="btnDlSel"[^>]*>下载选中字幕</.test(m), '主键不是「下载选中字幕」');
  assert.ok(/id="btnDownloadAll"[^>]*data-i18n="btnDlAll"[^>]*>下载全部字幕</.test(m), '缺「下载全部字幕」键');
  assert.ok(!/id="btnDownload"[^>]*data-i18n="btnDownload"/.test(m), '主键还挂着旧的 btnDownload 词条');
  /* 老的三态处理必须彻底拆掉 */
  assert.ok(!/Object\.keys\(ML\.results\)\.length > 1\)\{ mlDownloadZip\(\); return; \}/.test(m),
    '旧的三态处理还在（结果 >1 就偷偷打 zip）');
  assert.ok(/\$\('btnDownloadAll'\)\.addEventListener\('click'/.test(m), '全部键没接处理器');
});

t('v0.9.401：下载键只看矩阵里有没有成品，与预览无关', () => {
  const m = readT('multilang.html');
  assert.ok(/function syncDlBtns\(\)\{/.test(m), '缺 syncDlBtns');
  assert.ok(/var ok = !!dlTargetKey\(\) \|\| \(!n && dlDraftReady\(\)\);/.test(m), '可用性没按「有没有成品」算');
  assert.ok(/if\(ba\) ba\.disabled = !n;/.test(m), '全部键没按结果数置灰');
  assert.ok(/if\(bz\) bz\.disabled = !n;/.test(m), '顶栏下载键没跟上同一口径');
  /* 查看区不再是判据 —— 以前这两处各写一份 disabled，最容易分叉 */
  assert.ok(!/bd\.disabled = !Object\.keys\(ML\.results\)\.length/.test(m), 'viewerSet 里还留着旧判据');
  assert.ok(/syncDlBtns\(\);   \/\/ 2026-10-27/.test(m), 'viewerSet 空态没改成 syncDlBtns');
  assert.ok(/try\{ syncDlBtns\(\); \}catch\(e\)\{\}/.test(m), 'mxRender 没同步下载键');
  /* 选中格的解析顺序：选中格优先，其次「只有一格成品」 */
  assert.ok(/if\(ML\.selKey && ML\.results\[ML\.selKey\]\) return ML\.selKey;/.test(m), '选中格解析丢了');
});

t('v0.9.401：两键都按格上报，老结果有兜底', () => {
  const m = readT('multilang.html');
  assert.ok(/function dlMetaOf\(k\)\{/.test(m), '缺 dlMetaOf');
  assert.ok(/if\(c\.meta && \(c\.meta\.file \|\| c\.meta\.lang\)\) return c\.meta;/.test(m), '有 meta 时没优先用它');
  assert.ok(/reportEvent\('download', '', c\.fmt \|\| expFileFmt\(\), dlMetaOf\(k\), 'sel'\)/.test(m), '选中键没按格上报');
  assert.ok(/reportEvent\('download', '', \(r && r\.fmt\) \|\| expFileFmt\(\), dlMetaOf\(v\), 'all'\)/.test(m), '全部键没按格上报');
  assert.ok(!/if\(r && r\.meta\) reportEvent\('download'/.test(m), 'zip 仍然跳过没有 meta 的老结果');
  /* 复制与 zip 同口径：整季复制也要逐格记账 */
  assert.ok(/_ks\.map\(dlMetaOf\)/.test(m), '整季复制没按格上报');
  assert.ok(/metas\.forEach\(function\(m\)\{ reportEvent\('copy', '', '', m\); \}\)/.test(m), 'copyText 没逐格上报');
});

t('v0.9.401：27 语都补了下载两键的词条', () => {
  const D = readT('site-i18n.js');
  const re = /'([a-z]{2}(?:-[A-Z]{2})?)':\s*\{/g;
  const starts = [];
  let mm;
  while ((mm = re.exec(D))) starts.push([mm[1], mm.index]);
  assert.strictEqual(starts.length, 27, '语言块数不是 27：' + starts.length);
  starts.forEach(([lang, pos], i) => {
    const seg = D.slice(pos, i + 1 < starts.length ? starts[i + 1][1] : D.length);
    assert.ok(seg.indexOf("btnDlSel:'") > 0, lang + ' 缺 btnDlSel（会回落成中文）');
    assert.ok(seg.indexOf("btnDlAll:'") > 0, lang + ' 缺 btnDlAll（会回落成中文）');
  });
});

t('v0.9.401：服务端记下载方式，下载匹配窗口放宽到 24 小时', () => {
  const S = readT('server.js');
  const m = /const DL_SCOPE = (\{[^}]*\});/.exec(S);
  assert.ok(m, '缺 DL_SCOPE 白名单');
  const map = new Function('return ' + m[1] + ';')();
  assert.strictEqual(map.sel, 'dlSel', "scope='sel' 没映射到 dlSel");
  assert.strictEqual(map.all, 'dlAll', "scope='all' 没映射到 dlAll");
  assert.ok(/if \(dsc\) e\[dsc\] = \(e\[dsc\] \|\| 0\) \+ 1;/.test(S), '云端记录没累加下载方式');
  assert.ok(/if \(ls\) lite\[ls\] = 1;/.test(S), '自带 Key 记录没累加下载方式');
  assert.ok(/const EVENT_DL_MS = 24 \* 60 \* 60 \* 1000;/.test(S), '缺 24 小时下载窗口');
  assert.ok(/const life = dlLong \? EVENT_DL_MS : EVENT_LIFE_MS;/.test(S), '匹配循环没用上窗口');
  assert.ok(/dlSelTotal: all\.reduce/.test(S) && /dlAllTotal: all\.reduce/.test(S), '汇总缺两个新字段');
  /* 老口径不能被顺手改掉 */
  assert.ok(/const EVENT_LIFE_MS = 3 \* 60 \* 60 \* 1000;/.test(S), '3 小时窗口被改掉了');
});

t('v0.9.401：任务之间空 5 秒再进队列', () => {
  const m = readT('multilang.html');
  assert.ok(/var ML_TASK_GAP_MS = 5000;/.test(m), '间隔不是 5 秒');
  assert.ok(/if\(i < total - 1 && !ML\.stopReq\) await mlTaskGap\(ML_TASK_GAP_MS\);/.test(m),
    '换任务时没等间隔（或末尾任务也在空等）');
  assert.ok(/ML\.stopReq \|\| Date\.now\(\) - t0 >= ms/.test(m), '等待期间不响应停止');
  /* ETA 必须含间隔，否则用户按旧数字等，会以为卡住了 */
  assert.ok(/etaSec \+= Math\.max\(0, tasks\.length - 1\) \* \(ML_TASK_GAP_MS \/ 1000\);/.test(m),
    '预计耗时没算任务间隔');
  assert.ok(/mlt\('gapNote', ML_TASK_GAP_MS \/ 1000\)/.test(m), '计划里没说明间隔');
  /* 新词条：MXT 3 语、MLT 12 语 */
  /* ⚠️ 必须从 `var MXT = {` 之后再找语言块：文件前面的 MLT 也有 'zh-CN': {，
     直接 indexOf 会切到翻译文案那块去，断言永远失败（或永远通过）。 */
  const mx = m.indexOf('var MXT = {');
  assert.ok(mx > 0, '找不到 MXT 词典');
  ['zh-CN', 'zh-TW', 'en'].forEach(l => {
    const i = m.indexOf("'" + l + "': {", mx);
    assert.ok(i > mx, 'MXT 缺 ' + l);
    const seg = m.slice(i, m.indexOf("'", i + 5) > 0 ? i + 2000 : i + 2000);
    assert.ok(seg.indexOf('dlSelTip:') > 0, 'MXT ' + l + ' 缺 dlSelTip');
  });
  assert.strictEqual((m.match(/gapNote:/g) || []).length, 12, 'MLT 的 gapNote 不是 12 语');
});

t('v0.9.401：确认弹窗关掉后的空窗期挡连点', () => {
  const m = readT('multilang.html');
  /* 空窗期 = await mlConfirm 返回 → ML.running 置位之间。这段里再点一次会起两条队列，
     两套 taskId 各跑同一批任务，后台请求量翻倍。用 starting 这个同步锁挡住。 */
  assert.ok(/starting: false/.test(m), 'ML 状态对象里没有 starting 字段（动态字段也行，但要能一眼看到）');
  assert.ok(/if\(ML\.starting\) \{[^\n]*return; \}/.test(m), '没有连点拦截');
  assert.ok(/ML\.starting = true;/.test(m), '锁没上');
  /* 上锁后必须保证任何结局都能解锁：成功、抛错、被停止。 */
  assert.ok(/\.then\(function\(\)\{ ML\.starting = false; \}\)/.test(m), '队列结束后没解锁');
  assert.ok(/\}catch\(e\)\{ ML\.starting = false; \}/.test(m), '起队列同步抛错时没解锁');
});

/* ============================================================================
   v0.9.404：本机可以存多部片的进度
   用户原话：「我希望可以浏览器缓存用户翻译过的多个字幕进度，这样用户重启翻译的时候，
             可以从断点重新翻译，或者直接用之前翻译存下来的」
   改之前整页共用一个固定键 srt_resume_v1 —— 翻 A 到一半去翻 B，A 的进度当场被挤掉，
   而且用户根本看不见本机存了什么。改法：按「内容哈希 + 目标语言」分槽 + 一份索引，
   存储逻辑两页共用一份（snap-store.js），再各加一个「本机记录」面板能看能删。
   ⚠️ 存储层的行为细节由 test-snap.js 逐条盯（分槽 / LRU / 迁移 / 过期 / 空译文作废）；
      这里只锁「两页有没有接上」这件事 —— 页面是手抄副本，最容易出的就是只改了一页。
   ============================================================================ */
t('v0.9.404：两页的快照读写都走 snap-store.js，不再各写一份', () => {
  const ws = readT('translate.html'), ml = readT('multilang.html');
  assert.ok(/<script src="snap-store\.js\?v=0\.9\.406">/.test(ws), '翻译页没引入快照存储层');
  assert.ok(/<script src="snap-store\.js\?v=0\.9\.406">/.test(ml), '多语页没引入快照存储层');
  [['translate', ws], ['multilang', ml]].forEach(p => {
    const nm = p[0], s = p[1];
    assert.ok(/SnapStore\.write\(SNAP_KEY, fp,/.test(s), nm + ' 的 saveSnap 没走存储层（会绕过索引与容量治理）');
    assert.ok(/SnapStore\.read\(SNAP_KEY, fp, SNAP_KEY_LEGACY\)/.test(s),
      nm + ' 的 loadSnap 没走存储层，或没传老单键（v0.9.403 及以前正在续跑的任务会丢进度）');
    assert.ok(/SnapStore\.remove\(SNAP_KEY\)/.test(s), nm + ' 的 rmSnap 没走存储层（索引里会留幽灵条目）');
    assert.ok(/SnapStore\.finish\(SNAP_KEY\)/.test(s), nm + ' 的 markSnapDone 没走存储层');
  });
  /* 两页都不许再直接碰 localStorage 里的槽键 —— 那是漂移的起点 */
  assert.ok(!/localStorage\.setItem\(SNAP_KEY/.test(ws) && !/localStorage\.setItem\(SNAP_KEY/.test(ml),
    '还有页面在直接写槽键（存储层被绕过）');
});

t('v0.9.404：翻译页不再用固定单键，按内容哈希 + 目标语言分槽', () => {
  const ws = readT('translate.html');
  assert.ok(!/const SNAP_KEY='srt_resume_v1'/.test(ws),
    '翻译页还在用固定单键（翻 A 到一半去翻 B，A 的进度就没了）');
  assert.ok(/SNAP_KEY = SnapStore\.keyFor\(srcFingerprint\(S\.srcItems\), cfg\.dst\);/.test(ws),
    '开翻时没按「内容哈希 + 目标语言」算槽键');
  /* 槽键必须在 loadSnap 之前算好，否则第一就读错槽（多语页 v0.9.373 踩过同一个坑） */
  const iK = ws.indexOf('SNAP_KEY = SnapStore.keyFor(');
  const iL = ws.indexOf('const snap=loadSnap(snapFpStr);');
  assert.ok(iK > 0 && iL > 0 && iK < iL, '槽键算在 loadSnap 之后');
  /* 槽键只含内容哈希与语言：参数（风格/行宽/术语表）走 fp 校验，不能进键 */
  assert.ok(/keyFor\(fk, lang\)\{ return K_BASE \+ ':' \+ fk \+ ':' \+ lang; \}/.test(SNAP_SRC),
    'keyFor 的键格式变了（线上已有快照会全部失联）');
});

t('v0.9.404：两页都有「本机记录」入口，存了什么看得见、能删', () => {
  const ws = readT('translate.html'), ml = readT('multilang.html');
  assert.ok(/id="btnSnap"/.test(ws), '翻译页没有本机记录入口');
  assert.ok(/id="mlSnapBtn"/.test(ml), '多语页没有本机记录入口');
  assert.ok(/function openSnapPanel\(\)/.test(ws), '翻译页缺本机记录面板');
  assert.ok(/function mlOpenSnapPanel\(\)/.test(ml), '多语页缺本机记录面板');
  /* 面板必须真的读索引，不是写死的假列表 */
  assert.ok(/const items=SnapStore\.list\(\);/.test(ws), '翻译页面板没读快照索引');
  assert.ok(/var items = SnapStore\.list\(\);/.test(ml), '多语页面板没读快照索引');
  /* 打开前先清过期：不清的话面板会出现点了没反应的条目 */
  assert.ok(/SnapStore\.gc\(\)/.test(ws) && /SnapStore\.gc\(\)/.test(ml), '打开面板前没清理过期快照');
  /* 入口文案必须走 i18n —— 两页都是 27 语界面，写死中文等于非中文界面露中文 */
  assert.ok(/data-i18n="snapBtn"/.test(ws) && /data-i18n="snapBtn"/.test(ml),
    '入口按钮文案没走 i18n');
});

t('v0.9.404：本机记录的 7 个新词条补齐 27 语', () => {
  /* 新增词条必须 27 语齐全（v0.9.297 那条只查「块等长」，这里把具体键点名钉住，
     免得将来漏补时只报一个笼统的「不等长」） */
  const d = readT('site-i18n.js');
  ['snapBtn','snapTitle','snapEmpty','snapNote','snapDone','snapPart','snapLines'].forEach(k => {
    const n = (d.match(new RegExp('\\b' + k + ":'", 'g')) || []).length;
    assert.ok(n >= 27, k + ' 只有 ' + n + ' 个语言块（要求 27 语齐全）');
  });
});

t('v0.9.406：本机记录能直接把译文导成成品 srt（靠补存的 tl / gs）', () => {
  /* 用户提的：记录里点一下就该能导出。可快照原本只有 {编号:译文}，没有时间轴，
     连 srt 都拼不出来。这里把「补存 + 导出」整条链钉住。 */
  const ss = readT('snap-store.js');
  assert.ok(/function toSrt\(o\)\{/.test(ss), 'snap-store.js 缺 toSrt：导出没落地');
  assert.ok(/function fmtMs\(ms\)\{/.test(ss), '缺时间码格式化');
  /* peek 必须绕开校验：read() 遇到「过期 / 参数变了」会把槽删掉，
     而导出与参数对不对得上无关 —— 用户要的就是他翻出来的那些译文。 */
  assert.ok(/function peek\(key\)\{ return getObj\(key\); \}/.test(ss),
    'peek 走了校验路径（导出会把快照顺手删掉）');
  /* write 必须把时间轴落盘，否则导出永远是空的 */
  assert.ok(/tl:\(payload&&payload\.tl\)\|\|null/.test(ss) && /gs:\(payload&&payload\.gs\)\|\|null/.test(ss),
    'write 没把 tl/gs 存进快照（导出会拿不到时间轴）');
  /* 索引要带 hasTl，面板才知道哪条能导、哪条该置灰 */
  assert.ok(/hasTl:\(o\.tl && o\.gs\) \? 1 : 0/.test(ss), '索引没有 hasTl 字段');
  assert.ok(/hasTl:it\.hasTl\?1:0/.test(ss), 'list() 没把 hasTl 透出来');
  /* 两页都要把时间轴喂给 saveSnap */
  ;[['translate.html', readT('translate.html')], ['multilang.html', readT('multilang.html')]].forEach(p => {
    const h = p[1];
    assert.ok(/tl:SNAP_GEO\.tl, gs:SNAP_GEO\.gs/.test(h), p[0] + ' 的 saveSnap 没带 tl/gs');
    assert.ok(/SNAP_GEO = \{ tl:snapTimeline\(S\.srcItems\)/.test(h), p[0] + ' 没有算时间轴快照');
    /* 顺序很关键：必须在第一批 saveSnap 之前算好，否则第一批落地时 tl 还是 null */
    assert.ok(h.indexOf('SNAP_GEO = { tl:snapTimeline') < h.indexOf('saveSnap(snapFpStr'),
      p[0] + ' 的时间轴在第一批落盘之后才赋值（首个快照会缺时间轴）');
  });
  /* 面板上的下载入口：有 hasTl 才可点，没有就置灰并说明原因 */
  assert.ok(/function downloadSnapSrt\(item\)/.test(readT('translate.html')), '翻译页缺导出实现');
  assert.ok(/function mlDownloadSnap\(it\)/.test(readT('multilang.html')), '多语页缺导出实现');
  ;[['translate.html', readT('translate.html')], ['multilang.html', readT('multilang.html')]].forEach(p => {
    assert.ok(/it\.hasTl/.test(p[1]), p[0] + ' 的下载按钮没判 hasTl（老快照会点了没反应）');
    assert.ok(/t\('snapNoTl'\)/.test(p[1]), p[0] + ' 没解释「为什么导不出」');
  });
});

t('v0.9.406：导出的两个新词条补齐 27 语', () => {
  const d = readT('site-i18n.js');
  ['snapDl','snapNoTl'].forEach(k => {
    const n = (d.match(new RegExp('\\b' + k + ":'", 'g')) || []).length;
    assert.ok(n >= 27, k + ' 只有 ' + n + ' 个语言块（要求 27 语齐全）');
  });
});

t('v0.9.404：snap-store.js 万一没加载，两页不能整页崩', () => {
  /* snap-store.js 是本版新增的外链文件 —— 这是以前没有过的新变量。
     它一旦没部署上去（或 CDN 抽风没取到），顶层那几行 `SnapStore.SNAP_TTL`
     会直接 ReferenceError，整页脚本全军覆没，用户看到的是一个死页面。
     这与 v0.9.394 的 BUILTIN_API 血案是同一类：一个缺失的定义放倒整页。
     两页都必须备一份同名空壳兜底：功能降级为「没有断点」，页面照常能用。 */
  [['translate.html', readT('translate.html')], ['multilang.html', readT('multilang.html')]].forEach(p => {
    assert.ok(/if \(typeof SnapStore === 'undefined'\) \{/.test(p[1]),
      p[0] + ' 没有 SnapStore 兜底（外链文件一丢整页就崩）');
    /* 兜底必须提供页面顶层就用到的那几个字段，否则等于没兜 */
    const shim = p[1].slice(p[1].indexOf("if (typeof SnapStore === 'undefined') {"));
    const body = shim.slice(0, shim.indexOf('\n}'));
    ['K_BASE','SNAP_TTL','FIN_SNAP_TTL','keyFor','read','write','finish','remove','list','gc']
      .forEach(k => assert.ok(body.indexOf(k) >= 0, p[0] + ' 的兜底缺 ' + k));
  });
});

/* ---------------- v0.9.406：模型判「不用翻译」只救一次 ----------------
   线上 04:23 那单（1780 条 / 44 批）有 39 个批次各触发一次救援，救回条数远不抵请求成本。
   用户决策：模型说不用翻，试一次不行就算了。这三条测试锁的是「别再反复花钱」这条不变量。
   ⚠️ t() 是同步的（不 await），所以把块里的 await 去掉再同步跑：
      测的是「守卫 / 熔断」的控制流，跟 await 无关，去掉不影响结论。 */
t('v0.9.406：同一句组只救一次、连续零收获即熔断', () => {
  const h = readT('multilang.html');
  const s = h.indexOf('const rescueGnos=[];');
  assert.ok(s > 0, '没找到救援块起点');
  const o = h.indexOf('if(rescueGnos.length){', s);
  let d = 0, e = -1;
  for (let i = h.indexOf('{', o); i < h.length; i++) {
    if (h[i] === '{') d++;
    else if (h[i] === '}' && !--d) { e = i + 1; break; }
  }
  assert.ok(e > 0, '没找到救援块终点');
  const src = h.slice(s, e)
    .replace(/await\s+translateBatch\(/g, 'translateBatch(')
    .replace(/await\s+new Promise\([\s\S]*?\);/g, '0;');
  assert.ok(src.indexOf('await') < 0, '救援块里还有 await，同步跑不了');
  /* 阈值必须从源码读，不能写死 3 —— 否则改了源码里的常量，这条用例照样绿（变异测试实证过） */
  const lim = +(h.match(/const DROP_RESCUE_FAIL_LIMIT = (\d+);/) || [])[1];
  assert.ok(lim >= 1, '没读到 DROP_RESCUE_FAIL_LIMIT');
  const P = ['out', 'gBatch', 'S', 'translateBatch', 'log', 't', 'dropFillers', 'fillerSet',
    'DROP_RESCUE_FAIL_LIMIT', 'effBase', 'effKey', 'effModel', 'bi', 'totalB', 'sysB', 'ctx'];
  const run = new Function(...P, src);

  const mk = over => {
    const env = {
      out: Object.assign({ musicDropGnos: [], subDropGnos: [], byGno: {}, badAnchor: [] }, over.out || {}),
      gBatch: over.gBatch || [], S: Object.assign({}, over.S || {}),
      dropFillers: false, fillerSet: new Set(), DROP_RESCUE_FAIL_LIMIT: lim,
      logs: [], log: m => env.logs.push(String(m)), t: (k, n) => k + (n == null ? '' : ' ' + n),
      translateBatch: (b, k, m, gs) => {
        over.calls.push(gs.map(g => g.gno));
        return over.saved
          ? { byGno: { [over.saved]: { type: 'text', text: '译文' } }, badAnchor: [], fillers: new Set() }
          : { byGno: {}, badAnchor: [], fillers: new Set() };   // 零收获
      }
    };
    env.run = () => run(env.out, env.gBatch, env.S, env.translateBatch, env.log, env.t,
      env.dropFillers, env.fillerSet, env.DROP_RESCUE_FAIL_LIMIT, 'B', 'K', 'M', 0, 9, 'SYS', []);
    return env;
  };

  /* ① 同一组遇到两次（整批重发后再判 drop）→ 只发一次请求 */
  {
    const calls = [];
    const a = mk({ calls, gBatch: [{ gno: 7, text: '啊' }], out: { musicDropGnos: [7] }, S: { dropTried: null } });
    a.run(); a.run();
    assert.deepStrictEqual(calls, [[7]], '同一句组被救了两次（S.dropTried 没生效）');
    assert.strictEqual(a.S.dropSkipN, 1, 'dropSkipN 没记到跳过次数');
  }

  /* ② 连续 3 次零收获 → 熔断；第 4 组不再发请求 */
  {
    const calls = [];
    const N = lim + 1;
    const g = Array.from({ length: N }, (_, i) => ({ gno: i + 1, text: '啊' }));
    const S = { dropTried: null };
    for (let n = 1; n <= N; n++) {
      const x = mk({ calls, gBatch: g, out: { musicDropGnos: [n] }, S });
      x.run(); Object.assign(S, x.S);
      if (n === lim) assert.ok(x.logs.join('|').indexOf('dropRescueOff') >= 0, '熔断没打日志');
    }
    assert.deepStrictEqual(calls, Array.from({ length: lim }, (_, i) => [i + 1]), '熔断后仍在发救援请求');
    assert.strictEqual(S.dropRescueOff, 1, 'dropRescueOff 没置位');
    assert.strictEqual(S.dropRescueTryN, lim, 'dropRescueTryN 应为 ' + lim);
    assert.strictEqual(S.dropRescueFail, lim, 'dropRescueFail 应为 ' + lim);
  }

  /* ③ 中间救回一条 → 连败清零，不误熔断 */
  {
    const calls = [];
    const g = [1, 2, 3, 4, 5].map(n => ({ gno: n, text: '啊' }));
    const S = { dropTried: null };
    for (const [gno, saved] of [[1, 0], [2, 0], [3, 3], [4, 0], [5, 0]]) {   // 第 3 次救回 → 计数清零
      const x = mk({ calls, gBatch: g, out: { musicDropGnos: [gno] }, S, saved });
      x.run(); Object.assign(S, x.S);
    }
    assert.ok(!S.dropRescueOff, '中间救回一条后不该熔断');
    assert.strictEqual(S.dropRescueFail, 2, '救回后连败计数应清零（末两次连败 = 2，实际 ' + S.dropRescueFail + '）');
    assert.strictEqual(S.dropRescueFixN, 1, 'dropRescueFixN 应为 1');
  }
});

t('v0.9.406：SDH 画面/声音标注不算对白，不进救援也不计 subDrop', () => {
  const h = readT('multilang.html');
  const m = h.match(/function isScreenAnno\(s\)\{[\s\S]*?\n\}/);
  assert.ok(m, '没找到 isScreenAnno');
  const isScreenAnno = new Function(m[0] + ';return isScreenAnno;')();
  const yes = ['[speaking in French]', '[door creaks open]', '(laughs)', '♪', '[MUSIC] ♪♪', '（音乐）', '[ sighs ]'];
  const no = ['(in French) Ferme la porte.', '[speaking Spanish] Hola.', 'Open the door.', '♪ Hold me where the river bends ♪'];
  yes.forEach(s => assert.strictEqual(isScreenAnno(s), true, '应判为标注：' + s));
  no.forEach(s => assert.strictEqual(isScreenAnno(s), false, '不该判为标注：' + s));
  /* 口径必须与 subDrop 的过滤一致，否则告警仍会被标注撑大 */
  const subLine = h.split('\n').filter(x => x.indexOf('S.subDrop = S.rows.filter') >= 0).join('\n');
  assert.ok(/isScreenAnno\(String\(r\.en/.test(subLine), 'subDrop 重算没排除 SDH 标注');
  assert.ok(/if\(isScreenAnno\(dropSrc\)\) S\.dropSdhN=\(S\.dropSdhN\|\|0\)\+1;/.test(h),
    'drop 分类没单独记 dropSdhN');
  /* 歌词组也要有实义才救：♪ Oh-oh ♪ 这类由模型自己判断，救一次纯属白花钱 */
  assert.ok(/C\.musicRe\(\)\.test\(String\(g\.text\)\) && eff >= 6 && !C\.isPureHumming\(g\.text\)\) musicDropGnos/.test(h),
    '歌词组没加「有效字符 ≥6」门槛');
});

t('v0.9.406：救援遥测字段进账本白名单，27 语词条齐', () => {
  const srv = readT('server.js');
  ['dropRescueTryN', 'dropRescueFixN', 'dropSkipN', 'dropRescueOff', 'dropSdhN'].forEach(k => {
    assert.ok(srv.indexOf("'" + k + "'") >= 0, 'server.js 白名单缺 ' + k);
  });
  const d = readT('site-i18n.js');
  ['dropRescueOff', 'dropSkipNote'].forEach(k => {
    const n = (d.match(new RegExp('\\b' + k + ":'", 'g')) || []).length;
    assert.ok(n >= 27, k + ' 只有 ' + n + ' 个语言块（要求 27 语齐全）');
  });
});
